      return NextResponse.json(
        { 
          success: false,
          error: 'Validation error',
          message: 'Primary color and overall impression are required'
        },
        { status: 400 }
      );
    }

    const analysis = await prisma.gemstoneAnalysis.create({
      data: {
        imageUrl,
        imageName,
        primaryColor,
        secondaryColors: secondaryColors || [],
        luminanceSaturation,
        spectralCharacteristic,
        giaColorGrade,
        overallImpression,
        pleochroism: pleochroism || null,
        whitepoint: whitepoint || 'D65',
        kValue: kValue !== undefined && kValue !== null ? Number(kValue) : null,
        maskingOptions: maskingOptions || null,
        customPalette: customPalette || null,
        paletteComparisons: paletteComparisons || null,
        locale,
        notes: notes || null,
        tags: tags || [],
        published,
        featured,
        createdById: session.user.id,
      },
      include: {
        createdBy: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
      },
    });

    return NextResponse.json({ success: true, analysis }, { status: 201 });

  } catch (error) {
    console.error('Error creating gemstone analysis:', error);

    // Handle specific Prisma errors
    if (error && typeof error === 'object' && 'code' in error) {
      const prismaError = error as { code: string; message?: string };
      if (prismaError.code === 'P2002') {
        return NextResponse.json(
          { 
            success: false,
            error: 'Duplicate entry',
            message: 'An analysis with this data already exists'
          },
          { status: 409 }
        );
      }
    }

    return NextResponse.json(
      { 
        success: false,
        error: 'Failed to create analysis',
        message: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

'use client';

import { useState, useRef } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Textarea } from '@/components/ui/textarea';
import { Upload, FileJson, FileSpreadsheet, FileText, AlertCircle, CheckCircle, Loader2, Copy } from 'lucide-react';
import { useRouter } from 'next/navigation';
import Papa from 'papaparse';
import * as XLSX from 'xlsx';
import * as yaml from 'yaml';

interface BulkImportDialogProps {
  locale: string;
}

type FileFormat = 'json' | 'csv' | 'excel' | 'yaml';

export function BulkImportDialog({ locale }: BulkImportDialogProps) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<FileFormat>('json');
  const [textInput, setTextInput] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const parseFile = async (file: File): Promise<any[]> => {
    const extension = file.name.split('.').pop()?.toLowerCase();

    if (extension === 'json') {
      const text = await file.text();
      const data = JSON.parse(text);
      return Array.isArray(data) ? data : [data];
    } else if (extension === 'csv') {
      const text = await file.text();
      const result = Papa.parse(text, { header: true, skipEmptyLines: true });
      return result.data.map((row: any) => ({
        name: row.name || '',
        origin: row.origin || null,
        gia: {
          hue: row.gia_hue || row.hue || '',
          tone: row.gia_tone || row.tone || '',
          sat: row.gia_sat || row.sat || '',
        },
        gradient: row.gradient ? row.gradient.split(',').map((c: string) => c.trim()).filter(Boolean) : [],
        pleochro: row.pleochro ? row.pleochro.split(',').map((c: string) => c.trim()).filter(Boolean) : [],
        light: row.light || 'D55, CRI ≥95',
        note: row.note || null,
        description: row.description || null,
        published: row.published === 'true' || row.published === true,
        featured: row.featured === 'true' || row.featured === true,
        order: parseInt(row.order) || 0,
      }));
    } else if (extension === 'xlsx' || extension === 'xls') {
      const arrayBuffer = await file.arrayBuffer();
      const workbook = XLSX.read(arrayBuffer, { type: 'array' });
      const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
      const jsonData = XLSX.utils.sheet_to_json(firstSheet);
      return jsonData.map((row: any) => ({
        name: row.name || '',
        origin: row.origin || null,
        gia: {
          hue: row.gia_hue || row.hue || '',
          tone: row.gia_tone || row.tone || '',
          sat: row.gia_sat || row.sat || '',
        },
        gradient: row.gradient
          ? (typeof row.gradient === 'string'
              ? row.gradient.split(',').map((c: string) => c.trim()).filter(Boolean)
              : Array.isArray(row.gradient) ? row.gradient : [])
          : [],
        pleochro: row.pleochro
          ? (typeof row.pleochro === 'string'
              ? row.pleochro.split(',').map((c: string) => c.trim()).filter(Boolean)
              : Array.isArray(row.pleochro) ? row.pleochro : [])
          : [],
        light: row.light || 'D55, CRI ≥95',
        note: row.note || null,
        description: row.description || null,
        published: row.published === true || row.published === 'true',
        featured: row.featured === true || row.featured === 'true',
        order: parseInt(row.order) || 0,
      }));
    } else if (extension === 'yaml' || extension === 'yml') {
      const text = await file.text();
      const data = yaml.parse(text);
      return Array.isArray(data) ? data : [data];
    } else {
      throw new Error(`Unsupported file format: .${extension}`);
    }
  };

  const parseText = (text: string): any[] => {
    switch (activeTab) {
      case 'json':
        const data = JSON.parse(text);
        return Array.isArray(data) ? data : [data];
      case 'csv':
        const result = Papa.parse(text, { header: true, skipEmptyLines: true });
        return result.data.map((row: any) => ({
          name: row.name || '',
          origin: row.origin || null,
          gia: {
            hue: row.gia_hue || row.hue || '',
            tone: row.gia_tone || row.tone || '',
            sat: row.gia_sat || row.sat || '',
          },
          gradient: row.gradient ? row.gradient.split(',').map((c: string) => c.trim()).filter(Boolean) : [],
          pleochro: row.pleochro ? row.pleochro.split(',').map((c: string) => c.trim()).filter(Boolean) : [],
          light: row.light || 'D55, CRI ≥95',
          note: row.note || null,
          description: row.description || null,
          published: row.published === 'true' || row.published === true,
          featured: row.featured === 'true' || row.featured === true,
          order: parseInt(row.order) || 0,
        }));
      case 'yaml':
        const yamlData = yaml.parse(text);
        return Array.isArray(yamlData) ? yamlData : [yamlData];
      default:
        throw new Error('Text input only available for JSON, CSV, and YAML');
    }
  };

  const handleFile = async (file: File) => {
    setError(null);
    setSuccess(null);
    setIsUploading(true);

    try {
      const charts = await parseFile(file);

      await importCharts(charts);
    } catch (err) {
      setError(`Fehler beim Importieren: ${err instanceof Error ? err.message : 'Unbekannter Fehler'}`);
      setIsUploading(false);
    }
  };

  const handleTextInput = async () => {
    setError(null);
    setSuccess(null);
    setIsUploading(true);

    if (!textInput.trim()) {
      setError('Bitte geben Sie Daten ein.');
      setIsUploading(false);
      return;
    }

    try {
      const charts = parseText(textInput);
      await importCharts(charts);
      setTextInput('');
    } catch (err) {
      setError(`Fehler beim Parsen: ${err instanceof Error ? err.message : 'Unbekannter Fehler'}`);
      setIsUploading(false);
    }
  };

  const importCharts = async (charts: any[]) => {
    const response = await fetch('/api/color-charts/import', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        charts,
        locale,
      }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.error || 'Import fehlgeschlagen');
    }

    const result = await response.json();

    if (result.results.errors.length > 0 && result.results.success.length === 0) {
      setError(`Import fehlgeschlagen: ${result.results.errors.join(', ')}`);
    } else if (result.results.errors.length > 0) {
      setSuccess(`${result.imported} von ${result.total} Farbtafeln erfolgreich importiert.`);
      setError(`Einige Fehler: ${result.results.errors.slice(0, 3).join(', ')}${result.results.errors.length > 3 ? '...' : ''}`);
    } else {
      setSuccess(`${result.imported} Farbtafel(n) erfolgreich importiert!`);
    }

    // Refresh the page after successful import
    if (result.imported > 0) {
      setTimeout(() => {
        router.refresh();
        setOpen(false);
      }, 2000);
    }

    setIsUploading(false);
  };

  const getAcceptString = () => {
    switch (activeTab) {
      case 'json':
        return '.json';
      case 'csv':
        return '.csv';
      case 'excel':
        return '.xlsx,.xls';
      case 'yaml':
        return '.yaml,.yml';
      default:
        return '.json,.csv,.xlsx,.xls,.yaml,.yml';
    }
  };


  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      handleFile(file);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" className="flex items-center gap-2">
          <Upload className="h-4 w-4" />
          Bulk Import
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>Bulk Import von Farbtafeln</DialogTitle>
          <DialogDescription>
            Importieren Sie mehrere Farbtafeln gleichzeitig aus verschiedenen Formaten: JSON, CSV, Excel oder YAML.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {/* Error/Success messages */}
          {error && (
            <div className="flex items-center gap-2 p-3 bg-red-900/20 border border-red-700 rounded-lg text-red-400">
              <AlertCircle className="h-5 w-5" />
              <span className="text-sm">{error}</span>
            </div>
          )}

          {success && (
            <div className="flex items-center gap-2 p-3 bg-green-900/20 border border-green-700 rounded-lg text-green-400">
              <CheckCircle className="h-5 w-5" />
              <span className="text-sm">{success}</span>
            </div>
          )}

          {/* Format Tabs */}
          <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as FileFormat)}>
            <TabsList className="grid w-full grid-cols-4">
              <TabsTrigger value="json">
                <FileJson className="h-4 w-4 mr-1" />
                JSON
              </TabsTrigger>
              <TabsTrigger value="csv">
                <FileSpreadsheet className="h-4 w-4 mr-1" />
                CSV
              </TabsTrigger>
              <TabsTrigger value="excel">
                <FileSpreadsheet className="h-4 w-4 mr-1" />
                Excel
              </TabsTrigger>
              <TabsTrigger value="yaml">
                <FileText className="h-4 w-4 mr-1" />
                YAML
              </TabsTrigger>
            </TabsList>

            <TabsContent value={activeTab} className="space-y-4 mt-4">
              {/* Drop zone */}
              <div
                onDrop={(e) => {
                  e.preventDefault();
                  const file = e.dataTransfer.files[0];
                  if (file) handleFile(file);
                }}
                onDragOver={(e) => e.preventDefault()}
                className="border-2 border-dashed border-gray-600 rounded-lg p-8 text-center hover:border-[#9A1A63] transition-colors"
              >
                {activeTab === 'json' && <FileJson className="h-12 w-12 mx-auto mb-4 text-gray-400" />}
                {activeTab === 'csv' && <FileSpreadsheet className="h-12 w-12 mx-auto mb-4 text-gray-400" />}
                {activeTab === 'excel' && <FileSpreadsheet className="h-12 w-12 mx-auto mb-4 text-gray-400" />}
                {activeTab === 'yaml' && <FileText className="h-12 w-12 mx-auto mb-4 text-gray-400" />}
                <p className="text-gray-400 mb-2">
                  Ziehen Sie eine {activeTab.toUpperCase()}-Datei hierher oder klicken Sie zum Auswählen
                </p>
                <Button
                  variant="outline"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={isUploading}
                  className="mt-2"
                >
                  {isUploading ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Importiere...
                    </>
                  ) : (
                    <>
                      <Upload className="h-4 w-4 mr-2" />
                      Datei auswählen
                    </>
                  )}
                </Button>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept={getAcceptString()}
                  onChange={handleFileInput}
                  className="hidden"
                  disabled={isUploading}
                />
              </div>

              {/* Text Input (for JSON, CSV, YAML) */}
              {(activeTab === 'json' || activeTab === 'csv' || activeTab === 'yaml') && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <label className="text-sm text-gray-400">Oder direkt einfügen:</label>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => navigator.clipboard.readText().then(setTextInput)}
                      className="text-xs"
                    >
                      <Copy className="h-3 w-3 mr-1" />
                      Aus Zwischenablage
                    </Button>
                  </div>
                  <Textarea
                    value={textInput}
                    onChange={(e) => setTextInput(e.target.value)}
                    placeholder={`Fügen Sie ${activeTab.toUpperCase()}-Daten hier ein...`}
                    className="bg-gray-900/50 text-white border-gray-600 min-h-[150px] font-mono text-xs"
                  />
                  <Button
                    onClick={handleTextInput}
                    disabled={!textInput.trim() || isUploading}
                    className="w-full"
                  >
                    {isUploading ? (
                      <>
                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                        Importiere...
                      </>
                    ) : (
                      'Aus Text importieren'
                    )}
                  </Button>
                </div>
              )}
            </TabsContent>
          </Tabs>

          {/* Format examples */}
          <details className="mt-4">
            <summary className="text-sm text-gray-400 cursor-pointer hover:text-gray-300">
              Format-Beispiele anzeigen
            </summary>
            <div className="mt-2 space-y-4">
              {activeTab === 'json' && (
                <pre className="p-4 bg-gray-900/50 rounded-lg text-xs text-gray-300 overflow-x-auto">
                  {JSON.stringify(
                    [
                      {
                        name: 'Beispiel Farbtafel 1',
                        origin: 'Beispiel Herkunft',
                        gia: { hue: 'R', tone: '5', sat: '6' },
                        gradient: ['#FF0000', '#FF6666'],
                        pleochro: ['#FF0000'],
                        light: 'D55, CRI ≥95',
                      },
                      {
                        name: 'Beispiel Farbtafel 2',
                        origin: 'Beispiel Herkunft 2',
                        gia: { hue: 'B', tone: '4', sat: '5' },
                        gradient: ['#0000FF', '#6666FF'],
                        pleochro: ['#0000FF'],
                        light: 'D55, CRI ≥95',
                      },
                    ],
                    null,
                    2
                  )}
                </pre>
              )}
              {activeTab === 'csv' && (
                <div className="p-4 bg-gray-900/50 rounded-lg text-xs text-gray-300">
                  <p className="mb-2">CSV Header:</p>
                  <code className="block mb-2">name,origin,gia_hue,gia_tone,gia_sat,gradient,pleochro,light</code>
                  <p className="mb-2">Beispiel Zeilen:</p>
                  <code className="block mb-1">
                    &quot;Beispiel Farbtafel 1&quot;,&quot;Beispiel Herkunft&quot;,&quot;R&quot;,&quot;5&quot;,&quot;6&quot;,&quot;#FF0000,#FF6666&quot;,&quot;#FF0000&quot;,&quot;D55, CRI ≥95&quot;
                  </code>
                  <code className="block">
                    &quot;Beispiel Farbtafel 2&quot;,&quot;Beispiel Herkunft 2&quot;,&quot;B&quot;,&quot;4&quot;,&quot;5&quot;,&quot;#0000FF,#6666FF&quot;,&quot;#0000FF&quot;,&quot;D55, CRI ≥95&quot;
                  </code>
                </div>
              )}
              {activeTab === 'yaml' && (
                <pre className="p-4 bg-gray-900/50 rounded-lg text-xs text-gray-300 overflow-x-auto">
                  {`- name: Beispiel Farbtafel 1
  origin: Beispiel Herkunft
  gia:
    hue: R
    tone: 5
    sat: 6
  gradient:
    - "#FF0000"
    - "#FF6666"
  pleochro:
    - "#FF0000"
  light: D55, CRI ≥95
- name: Beispiel Farbtafel 2
  origin: Beispiel Herkunft 2
  gia:
    hue: B
    tone: 4
    sat: 5
  gradient:
    - "#0000FF"
    - "#6666FF"
  pleochro:
    - "#0000FF"
  light: D55, CRI ≥95`}
                </pre>
              )}
              {activeTab === 'excel' && (
                <div className="p-4 bg-gray-900/50 rounded-lg text-xs text-gray-300">
                  <p className="mb-2">Excel Spalten:</p>
                  <code className="block mb-2">
                    name | origin | gia_hue | gia_tone | gia_sat | gradient | pleochro | light
                  </code>
                  <p className="mt-2 text-gray-400">
                    Gradient und Pleochro können als komma-separierte Werte eingegeben werden.
                  </p>
                </div>
              )}
            </div>
          </details>
        </div>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Button } from '@/components/ui/button';
import { GradientBar } from '@/components/color-charts/GradientBar';
import { GemColorCard, ColorChart } from '@/components/color-charts/GemColorCard';

interface ColorChartEditorProps {
  chart?: ColorChart;
  locale: string;
  mode: 'create' | 'edit';
}

export function ColorChartEditor({ chart, locale, mode }: ColorChartEditorProps) {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: chart?.name || '',
    origin: chart?.origin || '',
    gia: {
      hue: (chart?.gia as any)?.hue || '',
      tone: (chart?.gia as any)?.tone || '',
      sat: (chart?.gia as any)?.sat || '',
    },
    gradient: chart?.gradient || ['#FFFFFF'],
    pleochro: chart?.pleochro || [],
    light: chart?.light || 'D55, CRI ≥95',
    note: chart?.note || '',
    description: chart?.description || '',
    published: chart?.published || false,
    featured: chart?.featured || false,
    order: chart?.order || 0,
  });

  const [newGradientColor, setNewGradientColor] = useState('#FFFFFF');
  const [newPleochroColor, setNewPleochroColor] = useState('#FFFFFF');

  const handleInputChange = (field: string, value: any) => {
    if (field.startsWith('gia.')) {
      const giaField = field.split('.')[1];
      setFormData(prev => ({
        ...prev,
        gia: {
          ...prev.gia,
          [giaField]: value,
        },
      }));
    } else {
      setFormData(prev => ({ ...prev, [field]: value }));
    }
  };

  const addGradientColor = () => {
    if (newGradientColor.match(/^#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})$/)) {
      setFormData(prev => ({
        ...prev,
        gradient: [...prev.gradient, newGradientColor],
      }));
      setNewGradientColor('#FFFFFF');
    }
  };

  const removeGradientColor = (index: number) => {
    setFormData(prev => ({
      ...prev,
      gradient: prev.gradient.filter((_, i) => i !== index),
    }));
  };

  const addPleochroColor = () => {
    if (newPleochroColor.match(/^#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})$/)) {
      setFormData(prev => ({
        ...prev,
        pleochro: [...prev.pleochro, newPleochroColor],
      }));
      setNewPleochroColor('#FFFFFF');
    }
  };

  const removePleochroColor = (index: number) => {
    setFormData(prev => ({
      ...prev,
      pleochro: prev.pleochro.filter((_, i) => i !== index),
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const url = mode === 'create'
        ? '/api/color-charts'
        : `/api/color-charts/${chart?.id}`;

      const method = mode === 'create' ? 'POST' : 'PUT';

      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...formData,
          locale,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Fehler beim Speichern');
      }

      router.push(`/${locale}/admin/color-charts`);
      router.refresh();
    } catch (error) {
      console.error('Error saving color chart:', error);
      alert(`Fehler: ${error instanceof Error ? error.message : 'Unbekannter Fehler'}`);
    } finally {
      setIsLoading(false);
    }
  };

  // Preview chart data
  const previewChart: ColorChart = {
    id: chart?.id || 'preview',
    name: formData.name || 'Vorschau',
    origin: formData.origin || null,
    locale,
    gia: formData.gia,
    gradient: formData.gradient,
    pleochro: formData.pleochro,
    light: formData.light,
    note: formData.note || null,
    description: formData.description || null,
    published: formData.published,
    featured: formData.featured,
    order: formData.order,
    createdAt: chart?.createdAt || new Date(),
    updatedAt: chart?.updatedAt || new Date(),
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Left Column: Form */}
        <div className="space-y-6">
          {/* Basic Information */}
          <Card className="bg-gray-800/50 border-gray-700">
            <CardHeader>
              <CardTitle className="text-white">Basis-Informationen</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label htmlFor="name" className="text-white">Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => handleInputChange('name', e.target.value)}
                  className="bg-gray-700 text-white border-gray-600"
                  required
                />
              </div>
              <div>
                <Label htmlFor="origin" className="text-white">Herkunft</Label>
                <Input
                  id="origin"
                  value={formData.origin}
                  onChange={(e) => handleInputChange('origin', e.target.value)}
                  className="bg-gray-700 text-white border-gray-600"
                />
              </div>
            </CardContent>
          </Card>

          {/* GIA Data */}
          <Card className="bg-gray-800/50 border-gray-700">
            <CardHeader>
              <CardTitle className="text-white">GIA-Daten</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label htmlFor="gia-hue" className="text-white">Hue</Label>
                <Input
                  id="gia-hue"
                  value={formData.gia.hue}
                  onChange={(e) => handleInputChange('gia.hue', e.target.value)}
                  className="bg-gray-700 text-white border-gray-600"
                  placeholder="z.B. pkR–R (pinkish Red → Red)"
                />
              </div>
              <div>
                <Label htmlFor="gia-tone" className="text-white">Tone</Label>
