                {/* Borderline v4: Enhanced Features */}
                <div className="space-y-2 pt-2 border-t border-gray-700">
                  <h4 className="text-sm font-medium text-gray-300">Borderline v4: Erweiterte Features</h4>

                  {/* Auto-K via GMM+BIC */}
