              analysis={overallImpression}
              canEdit={true} // Always allow editing for all users
              isLoggedIn={!!session?.user} // Show learning system info only for logged-in users
              onVarietyCorrection={async (correctedVariety: string[]) => {
                // Update local state
                const updatedImpression = {
                  ...overallImpression,
                  correctedVariety,
                };
                setOverallImpression(updatedImpression);

                // Check consistency and auto-update pleochroism if needed
                const { suggestPleochroismFromVarieties } = await import('./utils/gemstoneAnalysis');
                const suggestedPleochroism = suggestPleochroismFromVarieties(correctedVariety);
                const currentPleochroismType = (overallImpression.correctedPleochroism || overallImpression.pleochroism || '').toLowerCase().includes('isotrop') ? 'isotrop' : 'anisotrop';

                // If pleochroism doesn't match, update it automatically
                if (suggestedPleochroism !== currentPleochroismType) {
                  const newPleochroism = suggestedPleochroism === 'isotrop' 
                    ? 'Isotrop (kein Pleochroismus)' 
                    : 'Anisotrop (Pleochroismus vorhanden)';
                  setPleochroism(newPleochroism);

                  const newOverallImpression = generateOverallImpression(
                    overallImpression.dominantColorTone,
                    overallImpression.saturation,
                    newPleochroism,
                    overallImpression.opticalQuality
                  );
                  const newEvaluation = generateFinalEvaluation(
                    overallImpression.dominantColorTone,
                    overallImpression.saturation,
                    newPleochroism,
                    correctedVariety,
                    overallImpression.opticalQuality
                  );

                  setOverallImpression({
                    ...updatedImpression,
                    correctedPleochroism: newPleochroism,
                    pleochroism: newPleochroism,
                    overallImpression: newOverallImpression,
                    evaluation: newEvaluation,
                  });
                }

                // Save correction to API for learning (with both variety and pleochroism)
                if (primaryColorLab && session?.user) {
                  try {
                    const finalPleochroism = suggestedPleochroism === 'isotrop' 
                      ? 'Isotrop (kein Pleochroismus)' 
                      : 'Anisotrop (Pleochroismus vorhanden)';

                    await fetch('/api/gemstone-analyses/corrections', {
                      method: 'POST',
                      headers: {
                        'Content-Type': 'application/json',
                      },
                      body: JSON.stringify({
                        lab: primaryColorLab,
                        hex: primaryColor?.hex,
                        originalVariety: overallImpression.possibleVariety,
                        correctedVariety,
                        originalPleochroism: overallImpression.pleochroism,
                        correctedPleochroism: finalPleochroism,
                      }),
                    });
                  } catch (error) {
                    console.error('Error saving correction:', error);
                  }
                }
              }}
              onPleochroismCorrection={async (correctedPleochroism: string) => {
                // Update pleochroism state
                setPleochroism(correctedPleochroism);

                // Check consistency and auto-filter varieties if needed
                const { filterVarietiesByPleochroism, suggestPleochroismFromVarieties } = await import('./utils/gemstoneAnalysis');
                const displayVariety = overallImpression.correctedVariety && overallImpression.correctedVariety.length > 0
                  ? overallImpression.correctedVariety
                  : overallImpression.possibleVariety;

                const pleochroismType = correctedPleochroism.toLowerCase().includes('isotrop') ? 'isotrop' : 'anisotrop';
                const filteredVarieties = filterVarietiesByPleochroism(displayVariety, pleochroismType);

                // Auto-filter varieties to match pleochroism
                const finalVarieties = filteredVarieties.length > 0 ? filteredVarieties : displayVariety;

                // Regenerate overallImpression and evaluation with corrected pleochroism
                const newOverallImpression = generateOverallImpression(
                  overallImpression.dominantColorTone,
                  overallImpression.saturation,
                  correctedPleochroism,
                  overallImpression.opticalQuality
                );
                const newEvaluation = generateFinalEvaluation(
                  overallImpression.dominantColorTone,
                  overallImpression.saturation,
                  correctedPleochroism,
                  finalVarieties,
                  overallImpression.opticalQuality
                );

                // Update local state with corrected pleochroism and filtered varieties
                setOverallImpression({
                  ...overallImpression,
                  correctedPleochroism,
                  correctedVariety: finalVarieties.length !== displayVariety.length ? finalVarieties : overallImpression.correctedVariety,
                  pleochroism: correctedPleochroism,
                  overallImpression: newOverallImpression,
                  evaluation: newEvaluation,
                });

                // Save correction to API for learning (with both variety and pleochroism)
                if (primaryColorLab && session?.user) {
                  try {
                    await fetch('/api/gemstone-analyses/corrections', {
                      method: 'POST',
                      headers: {
                        'Content-Type': 'application/json',
                      },
                      body: JSON.stringify({
                        lab: primaryColorLab,
                        hex: primaryColor?.hex,
                        originalVariety: overallImpression.possibleVariety,
                        correctedVariety: finalVarieties,
                        originalPleochroism: overallImpression.pleochroism,
                        correctedPleochroism,
                      }),
                    });
                  } catch (error) {
                    console.error('Error saving correction:', error);
                  }
                }
              }}
            />
          )}
        </div>
      )}

      {/* Crop Tool Modal */}
      {showCropTool && imagePreview && (
        <GemstoneImageCrop
          imageUrl={imagePreview}
          onCrop={(region) => {
            setCropRegion(region);
            setShowCropTool(false);
          }}
          onClose={() => setShowCropTool(false)}
        />
      )}
    </div>
  );
}

'use client';

import { useState, useRef } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Textarea } from '@/components/ui/textarea';
import { Upload, FileJson, FileSpreadsheet, FileText, AlertCircle, CheckCircle, Copy } from 'lucide-react';
import Papa from 'papaparse';
import * as XLSX from 'xlsx';
import * as yaml from 'yaml';
import { ColorChart } from './GemColorCard';

interface UploadPanelProps {
  onImport: (charts: ColorChart[]) => void;
  className?: string;
}

type FileFormat = 'json' | 'csv' | 'excel' | 'yaml' | 'text';

export function UploadPanel({ onImport, className = '' }: UploadPanelProps) {
  const [isDragging, setIsDragging] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<FileFormat>('json');
  const [textInput, setTextInput] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const validateColorChart = (data: any): data is ColorChart => {
    return (
      typeof data === 'object' &&
      typeof data.name === 'string' &&
      Array.isArray(data.gradient) &&
      data.gradient.length > 0 &&
      Array.isArray(data.pleochro) &&
      typeof data.gia === 'object'
    );
  };

  const processCharts = (charts: any[]): { valid: ColorChart[]; errors: string[] } => {
    const validCharts: ColorChart[] = [];
    const errors: string[] = [];

    charts.forEach((chart, index) => {
      if (validateColorChart(chart)) {
        const validChart: ColorChart = {
          id: chart.id || `imported-${Date.now()}-${index}`,
          name: chart.name,
          origin: chart.origin || null,
          locale: chart.locale || 'de',
          gia: chart.gia || { hue: '', tone: '', sat: '' },
          gradient: chart.gradient,
          pleochro: chart.pleochro || [],
          light: chart.light || 'D55, CRI ≥95',
          note: chart.note || null,
          description: chart.description || null,
          published: chart.published || false,
          featured: chart.featured || false,
          order: chart.order || 0,
          createdAt: chart.createdAt ? new Date(chart.createdAt) : new Date(),
          updatedAt: chart.updatedAt ? new Date(chart.updatedAt) : new Date(),
        };
        validCharts.push(validChart);
      } else {
        errors.push(`Chart ${index + 1}: Ungültiges Format`);
      }
    });

    return { valid: validCharts, errors };
  };

  const handleJSON = (text: string) => {
    try {
      const data = JSON.parse(text);
      const charts = Array.isArray(data) ? data : [data];
      return processCharts(charts);
    } catch (err) {
      throw new Error(`JSON Parse Fehler: ${err instanceof Error ? err.message : 'Unbekannter Fehler'}`);
    }
  };

  const handleCSV = (text: string) => {
    try {
      const result = Papa.parse(text, {
        header: true,
        skipEmptyLines: true,
      });

      const charts = result.data.map((row: any) => {
        // Parse gradient and pleochro from comma-separated strings
        const gradient = row.gradient
          ? row.gradient.split(',').map((c: string) => c.trim()).filter(Boolean)
          : [];
        const pleochro = row.pleochro
          ? row.pleochro.split(',').map((c: string) => c.trim()).filter(Boolean)
          : [];

        return {
          name: row.name || '',
          origin: row.origin || null,
          gia: {
            hue: row.gia_hue || row.hue || '',
            tone: row.gia_tone || row.tone || '',
            sat: row.gia_sat || row.sat || '',
          },
          gradient,
          pleochro,
          light: row.light || 'D55, CRI ≥95',
          note: row.note || null,
          description: row.description || null,
          published: row.published === 'true' || row.published === true,
          featured: row.featured === 'true' || row.featured === true,
          order: parseInt(row.order) || 0,
        };
      });

      return processCharts(charts);
    } catch (err) {
      throw new Error(`CSV Parse Fehler: ${err instanceof Error ? err.message : 'Unbekannter Fehler'}`);
    }
  };

  const handleExcel = async (file: File) => {
    try {
      const arrayBuffer = await file.arrayBuffer();
      const workbook = XLSX.read(arrayBuffer, { type: 'array' });
      const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
      const jsonData = XLSX.utils.sheet_to_json(firstSheet);

      const charts = jsonData.map((row: any) => {
        const gradient = row.gradient
          ? (typeof row.gradient === 'string' 
              ? row.gradient.split(',').map((c: string) => c.trim()).filter(Boolean)
              : Array.isArray(row.gradient) ? row.gradient : [])
          : [];
        const pleochro = row.pleochro
          ? (typeof row.pleochro === 'string'
              ? row.pleochro.split(',').map((c: string) => c.trim()).filter(Boolean)
              : Array.isArray(row.pleochro) ? row.pleochro : [])
          : [];

        return {
          name: row.name || '',
          origin: row.origin || null,
          gia: {
            hue: row.gia_hue || row.hue || '',
            tone: row.gia_tone || row.tone || '',
            sat: row.gia_sat || row.sat || '',
          },
          gradient,
          pleochro,
          light: row.light || 'D55, CRI ≥95',
          note: row.note || null,
          description: row.description || null,
          published: row.published === true || row.published === 'true',
          featured: row.featured === true || row.featured === 'true',
          order: parseInt(row.order) || 0,
        };
      });

      return processCharts(charts);
    } catch (err) {
      throw new Error(`Excel Parse Fehler: ${err instanceof Error ? err.message : 'Unbekannter Fehler'}`);
    }
  };

  const handleYAML = (text: string) => {
    try {
      const data = yaml.parse(text);
      const charts = Array.isArray(data) ? data : [data];
      return processCharts(charts);
    } catch (err) {
      throw new Error(`YAML Parse Fehler: ${err instanceof Error ? err.message : 'Unbekannter Fehler'}`);
    }
  };

  const handleFile = async (file: File) => {
    setError(null);
    setSuccess(null);

    const extension = file.name.split('.').pop()?.toLowerCase();
    let result;

    try {
      if (extension === 'json') {
        const text = await file.text();
        result = handleJSON(text);
      } else if (extension === 'csv') {
        const text = await file.text();
        result = handleCSV(text);
      } else if (extension === 'xlsx' || extension === 'xls') {
        result = await handleExcel(file);
      } else if (extension === 'yaml' || extension === 'yml') {
        const text = await file.text();
        result = handleYAML(text);
      } else {
        setError(`Unsupported file format: .${extension}. Supported: .json, .csv, .xlsx, .yaml`);
        return;
      }

      if (result.errors.length > 0 && result.valid.length === 0) {
        setError(`Fehler beim Importieren: ${result.errors.join(', ')}`);
        return;
      }

      if (result.valid.length > 0) {
        onImport(result.valid);
        setSuccess(`${result.valid.length} Farbtafel(n) erfolgreich importiert!`);
        setTimeout(() => setSuccess(null), 5000);
      }

      if (result.errors.length > 0) {
        setError(`Einige Farbtafeln konnten nicht importiert werden: ${result.errors.join(', ')}`);
      }
    } catch (err) {
      setError(`Fehler beim Lesen der Datei: ${err instanceof Error ? err.message : 'Unbekannter Fehler'}`);
    }
  };

  const handleTextInput = () => {
    setError(null);
    setSuccess(null);

    if (!textInput.trim()) {
      setError('Bitte geben Sie Daten ein.');
      return;
    }

    try {
      let result;
      switch (activeTab) {
        case 'json':
          result = handleJSON(textInput);
          break;
        case 'csv':
          result = handleCSV(textInput);
          break;
        case 'yaml':
          result = handleYAML(textInput);
          break;
        default:
          setError('Text-Eingabe nur für JSON, CSV und YAML verfügbar.');
          return;
      }

      if (result.errors.length > 0 && result.valid.length === 0) {
        setError(`Fehler beim Importieren: ${result.errors.join(', ')}`);
        return;
      }

      if (result.valid.length > 0) {
        onImport(result.valid);
        setSuccess(`${result.valid.length} Farbtafel(n) erfolgreich importiert!`);
        setTextInput('');
        setTimeout(() => setSuccess(null), 5000);
      }

      if (result.errors.length > 0) {
        setError(`Einige Farbtafeln konnten nicht importiert werden: ${result.errors.join(', ')}`);
      }
    } catch (err) {
      setError(`Fehler beim Parsen: ${err instanceof Error ? err.message : 'Unbekannter Fehler'}`);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (file) {
      handleFile(file);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      handleFile(file);
    }
  };

  const getAcceptString = () => {
    switch (activeTab) {
      case 'json':
        return '.json';
      case 'csv':
        return '.csv';
      case 'excel':
        return '.xlsx,.xls';
      case 'yaml':
        return '.yaml,.yml';
      default:
        return '.json,.csv,.xlsx,.xls,.yaml,.yml';
    }
  };

  const loadDemo = () => {
    const demoChart: ColorChart = {
      id: 'demo-1',
      name: 'Demo Farbtafel',
      origin: 'Demo Herkunft',
      locale: 'de',
      gia: {
        hue: 'R (Red)',
        tone: '5 (Medium)',
        sat: '6 (Vivid)',
      },
      gradient: ['#FF0000', '#FF6666', '#FF9999', '#FFCCCC'],
      pleochro: ['#FF0000', '#FF6666'],
      light: 'D55, CRI ≥95',
      note: 'Dies ist eine Demo-Farbtafel',
      description: null,
      published: false,
      featured: false,
      order: 0,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    onImport([demoChart]);
    setSuccess('Demo-Farbtafel geladen!');
    setTimeout(() => setSuccess(null), 5000);
  };

  return (
    <Card className={`bg-gray-800/50 border-gray-700 ${className}`}>
      <CardHeader>
        <CardTitle className="text-white text-lg flex items-center gap-2">
          <Upload className="h-5 w-5" />
          Import von Farbtafeln
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <p className="text-sm text-gray-400">
          Importieren Sie Farbtafel-Daten in verschiedenen Formaten: JSON, CSV, Excel (XLSX) oder YAML.
        </p>

        {/* Error/Success messages */}
        {error && (
          <div className="flex items-center gap-2 p-3 bg-red-900/20 border border-red-700 rounded-lg text-red-400">
            <AlertCircle className="h-5 w-5" />
            <span className="text-sm">{error}</span>
          </div>
        )}

        {success && (
          <div className="flex items-center gap-2 p-3 bg-green-900/20 border border-green-700 rounded-lg text-green-400">
            <CheckCircle className="h-5 w-5" />
            <span className="text-sm">{success}</span>
          </div>
        )}

        {/* Format Tabs */}
        <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as FileFormat)}>
          <TabsList className="grid w-full grid-cols-4">
            <TabsTrigger value="json">
              <FileJson className="h-4 w-4 mr-1" />
              JSON
            </TabsTrigger>
            <TabsTrigger value="csv">
              <FileSpreadsheet className="h-4 w-4 mr-1" />
              CSV
            </TabsTrigger>
            <TabsTrigger value="excel">
              <FileSpreadsheet className="h-4 w-4 mr-1" />
              Excel
            </TabsTrigger>
            <TabsTrigger value="yaml">
              <FileText className="h-4 w-4 mr-1" />
              YAML
            </TabsTrigger>
          </TabsList>

          {/* File Upload */}
          <TabsContent value={activeTab} className="space-y-4 mt-4">
            {/* Drop zone */}
            <div
              onDrop={handleDrop}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              className={`
                border-2 border-dashed rounded-lg p-8 text-center transition-colors
                ${isDragging
                  ? 'border-[#9A1A63] bg-[#9A1A63]/10'
                  : 'border-gray-600 hover:border-gray-500'
                }
              `}
            >
              {activeTab === 'json' && <FileJson className="h-12 w-12 mx-auto mb-4 text-gray-400" />}
              {activeTab === 'csv' && <FileSpreadsheet className="h-12 w-12 mx-auto mb-4 text-gray-400" />}
              {activeTab === 'excel' && <FileSpreadsheet className="h-12 w-12 mx-auto mb-4 text-gray-400" />}
              {activeTab === 'yaml' && <FileText className="h-12 w-12 mx-auto mb-4 text-gray-400" />}
              <p className="text-gray-400 mb-2">
                Ziehen Sie eine {activeTab.toUpperCase()}-Datei hierher oder klicken Sie zum Auswählen
              </p>
              <Button
                variant="outline"
                onClick={() => fileInputRef.current?.click()}
                className="mt-2"
              >
                Datei auswählen
              </Button>
              <input
                ref={fileInputRef}
                type="file"
                accept={getAcceptString()}
                onChange={handleFileInput}
                className="hidden"
              />
            </div>

            {/* Text Input (for JSON, CSV, YAML) */}
            {(activeTab === 'json' || activeTab === 'csv' || activeTab === 'yaml') && (
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <label className="text-sm text-gray-400">Oder direkt einfügen:</label>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => navigator.clipboard.readText().then(setTextInput)}
                    className="text-xs"
                  >
                    <Copy className="h-3 w-3 mr-1" />
                    Aus Zwischenablage
                  </Button>
                </div>
                <Textarea
                  value={textInput}
                  onChange={(e) => setTextInput(e.target.value)}
                  placeholder={`Fügen Sie ${activeTab.toUpperCase()}-Daten hier ein...`}
                  className="bg-gray-900/50 text-white border-gray-600 min-h-[150px] font-mono text-xs"
                />
                <Button
                  onClick={handleTextInput}
                  disabled={!textInput.trim()}
                  className="w-full"
                >
                  Aus Text importieren
                </Button>
              </div>
            )}
          </TabsContent>
        </Tabs>

        {/* Demo button */}
        <div className="pt-4 border-t border-gray-700">
          <Button
            variant="outline"
            onClick={loadDemo}
            className="w-full"
          >
            Demo-Daten laden
          </Button>
        </div>

        {/* Format examples */}
        <details className="mt-4">
          <summary className="text-sm text-gray-400 cursor-pointer hover:text-gray-300">
            Format-Beispiele anzeigen
          </summary>
          <div className="mt-2 space-y-4">
            {activeTab === 'json' && (
              <pre className="p-4 bg-gray-900/50 rounded-lg text-xs text-gray-300 overflow-x-auto">
                {JSON.stringify(
                  {
                    name: 'Beispiel Farbtafel',
                    origin: 'Beispiel Herkunft',
                    gia: { hue: 'R', tone: '5', sat: '6' },
                    gradient: ['#FF0000', '#FF6666'],
                    pleochro: ['#FF0000'],
                    light: 'D55, CRI ≥95',
                  },
                  null,
                  2
                )}
              </pre>
            )}
            {activeTab === 'csv' && (
              <div className="p-4 bg-gray-900/50 rounded-lg text-xs text-gray-300">
                <p className="mb-2">CSV Header:</p>
                <code className="block mb-2">name,origin,gia_hue,gia_tone,gia_sat,gradient,pleochro,light</code>
                <p className="mb-2">Beispiel Zeile:</p>
                <code className="block">
                  "Beispiel Farbtafel","Beispiel Herkunft","R","5","6","#FF0000,#FF6666","#FF0000","D55, CRI ≥95"
                </code>
              </div>
            )}
            {activeTab === 'yaml' && (
              <pre className="p-4 bg-gray-900/50 rounded-lg text-xs text-gray-300 overflow-x-auto">
                {`name: Beispiel Farbtafel
origin: Beispiel Herkunft
gia:
  hue: R
  tone: 5
  sat: 6
gradient:
  - "#FF0000"
  - "#FF6666"
pleochro:
  - "#FF0000"
light: D55, CRI ≥95`}
              </pre>
            )}
            {activeTab === 'excel' && (
              <div className="p-4 bg-gray-900/50 rounded-lg text-xs text-gray-300">
                <p className="mb-2">Excel Spalten:</p>
                <code className="block">
                  name | origin | gia_hue | gia_tone | gia_sat | gradient | pleochro | light
                </code>
                <p className="mt-2 text-gray-400">
                  Gradient und Pleochro können als komma-separierte Werte eingegeben werden.
                </p>
              </div>
            )}
          </div>
        </details>
      </CardContent>
    </Card>
  );
}

/**
 * Enhanced Color Extraction with Borderline v4 Features
 * 
 * Provides enhanced versions of color extraction functions that integrate:
 * - SLIC Superpixels + Guided Filter for improved masking
 * - K-Means++ with Auto-K via GMM+BIC
 * - Borderline detection
 * - ICC profile support
 */

import {
  extractColorsFromImage,
  ImageAnalysis,
  ColorSample,
  MaskingOptions,
  DEFAULT_MASKING_OPTIONS,
  detectGemstoneMask,
  calculateColorPurity,
  rgbToHex,
  rgbToHsv,
} from './imageColorExtraction';
import { Whitepoint, getWhitepointXYZ, rgbToXyz, xyzToLab } from './colorConversions';
import { slicSuperpixels, majorityVoteMask } from './slicSuperpixels';
import { guidedFilterMaskWithImage } from './guidedFilter';
import { kmeansRGB, Cluster } from './kmeansPlusPlus';
import { gmmDiagBIC, getOptimalK } from './gmmBIC';
import { circularStatsDeg, softCategory, hueBorderlineFromHist } from './circularStats';
import { ICCProfile } from './iccParser';

export interface EnhancedMaskingOptions extends MaskingOptions {
  useSLIC?: boolean;
  slicStep?: number;
  slicM?: number;
  useGuidedFilter?: boolean;
  guidedR?: number;
  guidedEps?: number;
}

export interface EnhancedClusteringOptions {
  useAutoK?: boolean;
  autoKMin?: number;
  autoKMax?: number;
  useKMeansPP?: boolean;
  kValue?: number | null;
}

export interface EnhancedAnalysisResult extends ImageAnalysis {
  borderline?: {
    isBorderline: boolean;
    primaryCategory: string;
    secondaryCategory?: string;
    confidence: number;
    hueMean: number;
    hueR: number;
    peakSeparation: number;
  };
  clustering?: {
    k: number;
    autoK: boolean;
    method: 'kmeans++' | 'kmeans';
  };
  masking?: {
    usedSLIC: boolean;
    usedGuidedFilter: boolean;
  };
  params?: {
    whitepoint: Whitepoint;
    iccWP?: [number, number, number];
    masking: EnhancedMaskingOptions;
    clustering: EnhancedClusteringOptions;
  };
}

/**
 * Enhanced color extraction with Borderline v4 features
 */
export async function extractColorsEnhanced(
  imageFile: File,
  sampleSize: number = 10000,
  cropRegion?: { x: number; y: number; width: number; height: number },
  whitepoint: Whitepoint = 'D65',
  iccProfile?: ICCProfile | null,
  maskingOptions?: EnhancedMaskingOptions,
  clusteringOptions?: EnhancedClusteringOptions
): Promise<EnhancedAnalysisResult> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(imageFile);

    img.onload = async () => {
      try {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        if (!ctx) {
          reject(new Error('Could not get canvas context'));
          return;
        }

        canvas.width = img.width;
        canvas.height = img.height;
        ctx.drawImage(img, 0, 0);

        // Determine effective whitepoint (ICC > D50/D65 toggle)
        let effectiveWP: [number, number, number];
        if (iccProfile?.wtpt) {
          effectiveWP = iccProfile.wtpt;
        } else {
          effectiveWP = getWhitepointXYZ(whitepoint);
        }

        // Get masking options with defaults
        const maskOpts: EnhancedMaskingOptions = {
          ...DEFAULT_MASKING_OPTIONS,
          ...maskingOptions,
        };

        // Step 1: Enhanced mask detection
        let mask: boolean[][];
        let usedSLIC = false;
        let usedGuidedFilter = false;

        if (maskOpts.useSLIC || maskOpts.useGuidedFilter) {
          // Enhanced masking with SLIC + Guided Filter
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

          // Create initial mask
          const initialMask = new Uint8Array(canvas.width * canvas.height);
          for (let y = 0; y < canvas.height; y++) {
            for (let x = 0; x < canvas.width; x++) {
              const pixelData = ctx.getImageData(x, y, 1, 1);
              const r = pixelData.data[0];
              const g = pixelData.data[1];
              const b = pixelData.data[2];
              const luma = 0.2126 * r + 0.7152 * g + 0.0722 * b;
              const [h, s] = rgbToHsv(r, g, b);

              let keep = true;
              if (maskOpts.white && luma > (maskOpts.wThr || 220) && s < 30) keep = false;
              if (maskOpts.black && luma < (maskOpts.bThr || 25)) keep = false;
              if (maskOpts.lowSat && s < (maskOpts.sThr || 8)) keep = false;

              initialMask[y * canvas.width + x] = keep ? 255 : 0;
            }
          }

          let finalMask: Uint8Array = initialMask;

          // SLIC refinement
          if (maskOpts.useSLIC) {
            const slicResult = slicSuperpixels(
              imageData,
              maskOpts.slicStep || 16,
              maskOpts.slicM || 10
            );
            finalMask = majorityVoteMask(slicResult, initialMask);
            usedSLIC = true;
          }

          // Guided Filter
          if (maskOpts.useGuidedFilter) {
            finalMask = guidedFilterMaskWithImage(
              finalMask,
              imageData.data,
              canvas.width,
              canvas.height,
              maskOpts.guidedR || 4,
              maskOpts.guidedEps || 1e-3,
              0.5
            );
            usedGuidedFilter = true;
          }

          // Convert to boolean mask
          mask = [];
          for (let y = 0; y < canvas.height; y++) {
            mask[y] = [];
            for (let x = 0; x < canvas.width; x++) {
              mask[y][x] = finalMask[y * canvas.width + x] > 128;
            }
          }
        } else {
          // Standard masking
          mask = detectGemstoneMask(ctx, canvas.width, canvas.height, maskOpts);
        }

        // Step 2: Extract color samples
        const pixels: ColorSample[] = [];
        const hues: number[] = [];
        const hueHist = new Array(360).fill(0);

        const startX = cropRegion ? Math.max(0, cropRegion.x) : 0;
        const startY = cropRegion ? Math.max(0, cropRegion.y) : 0;
        const endX = cropRegion ? Math.min(canvas.width, cropRegion.x + cropRegion.width) : canvas.width;
        const endY = cropRegion ? Math.min(canvas.height, cropRegion.y + cropRegion.height) : canvas.height;

        const baseStep = Math.max(1, Math.floor(((endX - startX) * (endY - startY)) / sampleSize));

        for (let y = startY; y < endY; y += baseStep) {
          for (let x = startX; x < endX; x += baseStep) {
            if (!mask[y] || !mask[y][x]) continue;

            const imageData = ctx.getImageData(x, y, 1, 1);
            const r = imageData.data[0];
            const g = imageData.data[1];
            const b = imageData.data[2];
            if (imageData.data[3] < 128) continue;

            const hex = rgbToHex(r, g, b);
            const rgb = { r: r / 255, g: g / 255, b: b / 255 };
            const xyz = rgbToXyz(rgb);
            const lab = xyzToLab(xyz, whitepoint, effectiveWP);

            // Collect hue for borderline analysis
            const [h] = rgbToHsv(r, g, b);
            hues.push(h);
            hueHist[Math.floor(h) % 360]++;

            pixels.push({
              hex,
              rgb: { r, g, b },
              lab,
              xyz,
              percentage: 0,
              x,
              y,
              weight: 1,
            });
          }
        }

        // Step 3: Enhanced clustering
        const clusterOpts: EnhancedClusteringOptions = {
          useAutoK: true,
          autoKMin: 3,
          autoKMax: 8,
          useKMeansPP: true,
          ...clusteringOptions,
        };

        let clusters: ColorSample[];
        let finalK: number;
        let usedAutoK = false;

        if (clusterOpts.useAutoK && pixels.length > 100) {
          // Auto-K via GMM+BIC
          const points = pixels.map(p => [p.rgb.r * 255, p.rgb.g * 255, p.rgb.b * 255]);
          const gmmResult = gmmDiagBIC(points, clusterOpts.autoKMin || 3, clusterOpts.autoKMax || 8);
          finalK = getOptimalK(gmmResult);
          usedAutoK = true;
        } else {
          // Manual K
          finalK = clusterOpts.kValue || Math.min(Math.max(3, Math.floor(pixels.length / 100)), 20);
        }

        // Use K-Means++ in RGB space
        const rgbPoints = pixels.map(p => [p.rgb.r * 255, p.rgb.g * 255, p.rgb.b * 255]);
        const kmeansClusters = kmeansRGB(rgbPoints, finalK, 25, clusterOpts.useKMeansPP !== false);

        // Convert back to ColorSample format
        clusters = kmeansClusters.map((c) => {
          // Find closest pixel for Lab values
          let closestPixel = pixels[0];
          let minDist = Infinity;
          for (const p of pixels) {
            const dist = Math.sqrt(
              (p.rgb.r * 255 - c.rgb[0]) ** 2 +
              (p.rgb.g * 255 - c.rgb[1]) ** 2 +
              (p.rgb.b * 255 - c.rgb[2]) ** 2
            );
            if (dist < minDist) {
              minDist = dist;
              closestPixel = p;
            }
          }

          return {
            hex: c.hex,
            rgb: { r: c.rgb[0], g: c.rgb[1], b: c.rgb[2] },
            lab: closestPixel.lab,
            xyz: closestPixel.xyz,
            percentage: c.share * 100,
            x: 0,
            y: 0,
            weight: c.share,
          };
        });

        // Normalize percentages
        const total = clusters.reduce((sum, c) => sum + c.percentage, 0);
        if (total > 0) {
          clusters.forEach(c => {
            c.percentage = (c.percentage / total) * 100;
          });
        }

        // Step 4: Borderline analysis
        let borderlineAnalysis: EnhancedAnalysisResult['borderline'] | undefined;
        if (hues.length > 0) {
          const circStats = circularStatsDeg(hues);
          const category = softCategory(circStats.mean);
          const histAnalysis = hueBorderlineFromHist(hueHist, 3);

          borderlineAnalysis = {
            isBorderline: category.borderline,
            primaryCategory: category.primary.name,
            secondaryCategory: category.secondary?.name,
            confidence: category.conf,
            hueMean: circStats.mean,
            hueR: circStats.R,
            peakSeparation: histAnalysis.sepDeg,
          };
        }

        // Step 5: Calculate metrics
        const sorted = clusters.sort((a, b) => b.percentage - a.percentage);
        const primaryColor = sorted[0];
        const secondaryColors = sorted.slice(1, 5);

        const totalWeight = clusters.reduce((sum, c) => sum + (c.weight || c.percentage), 0);
        const avgL = totalWeight > 0
          ? clusters.reduce((sum, c) => sum + c.lab.L * (c.weight || c.percentage), 0) / totalWeight
          : clusters.reduce((sum, c) => sum + c.lab.L, 0) / clusters.length;

        const avgS = totalWeight > 0
          ? clusters.reduce((sum, c) => {
              const chroma = Math.sqrt(c.lab.a ** 2 + c.lab.b ** 2);
              return sum + chroma * (c.weight || c.percentage);
            }, 0) / totalWeight
          : clusters.reduce((sum, c) => {
              const chroma = Math.sqrt(c.lab.a ** 2 + c.lab.b ** 2);
              return sum + chroma;
            }, 0) / clusters.length;

        const colorPurity = calculateColorPurity(clusters, primaryColor);

        URL.revokeObjectURL(url);

        resolve({
          primaryColor,
          secondaryColors,
          allColors: clusters,
          luminance: avgL,
          saturation: avgS,
          colorPurity,
          borderline: borderlineAnalysis,
          clustering: {
            k: finalK,
            autoK: usedAutoK,
            method: clusterOpts.useKMeansPP !== false ? 'kmeans++' : 'kmeans',
          },
          masking: {
            usedSLIC,
            usedGuidedFilter,
          },
          params: {
            whitepoint,
            iccWP: iccProfile?.wtpt,
            masking: maskOpts,
            clustering: clusterOpts,
          },
        });
      } catch (error) {
        URL.revokeObjectURL(url);
        reject(error);
      }
    };

    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error('Failed to load image'));
    };

    img.src = url;
  });
}

/**
 * Gaussian Mixture Model (GMM) with diagonal covariance + BIC for Auto-K
 * 
 * Automatically determines the optimal number of clusters (K) using
 * Bayesian Information Criterion (BIC) to balance model complexity and fit.
 * 
 * Based on the Borderline v4 implementation with enhancements:
 * - Diagonal covariance matrix (faster than full covariance)
 * - K-Means++ initialization for better starting points
 * - BIC-based model selection
 * - Performance optimization for large datasets
 */

import { kmeansPlusPlusInit } from './kmeansPlusPlus';

export interface GMMResult {
  k: number;                    // Optimal number of clusters
  means: number[][];            // Cluster means [k][3] (RGB)
  vars: number[][];             // Cluster variances [k][3] (diagonal covariance)
  weights: number[];             // Cluster weights (sum to 1)
  bic: number;                  // Bayesian Information Criterion (lower is better)
  ll: number;                    // Log-likelihood
}

/**
 * Gaussian Mixture Model with diagonal covariance matrix and BIC-based model selection
 * 
 * Tests different values of K (Kmin to Kmax) and selects the one with lowest BIC.
 * Uses Expectation-Maximization (EM) algorithm for parameter estimation.
 * 
 * @param points Array of RGB points [r, g, b] where each value is 0-255
 * @param Kmin Minimum number of clusters (default: 3)
 * @param Kmax Maximum number of clusters (default: 8)
 * @param iters Number of EM iterations per K (default: 30)
 * @param maxPoints Maximum number of points to process (for performance, default: 50000)
 * @returns GMM result with optimal K and parameters
 */
export function gmmDiagBIC(
  points: number[][],
  Kmin: number = 3,
  Kmax: number = 8,
  iters: number = 30,
  maxPoints: number = 50000
): GMMResult {
  if (points.length === 0) {
    throw new Error('Points array is empty');
  }

  // Decimation for performance: if too many points, sample them
  let X: number[][];
  if (points.length > maxPoints) {
    const step = Math.ceil(points.length / maxPoints);
    X = [];
    for (let i = 0; i < points.length; i += step) {
      X.push([...points[i]]);
    }
  } else {
    X = points.map(p => [...p]);
  }

  const n = X.length;
  const d = 3; // RGB = 3 dimensions

  if (n < Kmin) {
    // Not enough points, return single cluster
    const mean = [0, 0, 0];
    for (let i = 0; i < n; i++) {
      mean[0] += X[i][0];
      mean[1] += X[i][1];
      mean[2] += X[i][2];
    }
    mean[0] /= n;
    mean[1] /= n;
    mean[2] /= n;

    return {
      k: 1,
      means: [mean],
      vars: [[100, 100, 100]],
      weights: [1.0],
      bic: 0,
      ll: 0,
    };
  }

  // Clamp Kmin and Kmax
  Kmin = Math.max(1, Math.min(Kmin, n));
  Kmax = Math.max(Kmin, Math.min(Kmax, n));

  /**
   * Expectation-Maximization for a specific K
   */
  function em(k: number): GMMResult {
    // Initialize means using K-Means++
    let means = kmeansPlusPlusInit(X, k).map(c => c.slice());

    // Initialize weights (uniform)
    let weights = Array(k).fill(1 / k);

    // Initialize variances (large start values for stability)
    let vars = Array.from({ length: k }, () => Array(d).fill(4000));

    // Responsibility matrix: resp[i][j] = probability that point i belongs to cluster j
    const resp = Array.from({ length: n }, () => Array(k).fill(0));

    // EM iterations
    for (let it = 0; it < iters; it++) {
      // E-step: Compute responsibilities
      for (let i = 0; i < n; i++) {
        let sumr = 0;

        for (let j = 0; j < k; j++) {
          // Compute probability density for diagonal Gaussian
          let p = 1;
          for (let t = 0; t < d; t++) {
            const diff = X[i][t] - means[j][t];
            const v = vars[j][t];
            // Gaussian PDF: exp(-0.5 * (x-μ)²/σ²) / sqrt(2πσ²)
            p *= Math.exp(-0.5 * diff * diff / v) / Math.sqrt(2 * Math.PI * v);
          }
          resp[i][j] = weights[j] * p;
          sumr += resp[i][j];
        }

        // Normalize responsibilities
        if (sumr === 0) {
          // Fallback: uniform distribution
          for (let j = 0; j < k; j++) {
            resp[i][j] = 1 / k;
          }
        } else {
          for (let j = 0; j < k; j++) {
            resp[i][j] /= sumr;
          }
        }
      }

      // M-step: Update parameters
      for (let j = 0; j < k; j++) {
        // Compute effective number of points in cluster j
        let Nj = 0;
        const mu = [0, 0, 0];

        for (let i = 0; i < n; i++) {
          Nj += resp[i][j];
          mu[0] += resp[i][j] * X[i][0];
          mu[1] += resp[i][j] * X[i][1];
          mu[2] += resp[i][j] * X[i][2];
        }

        // Update mean
        if (Nj > 0) {
          mu[0] /= Nj;
          mu[1] /= Nj;
          mu[2] /= Nj;
          means[j] = mu.slice();

          // Update variance (diagonal)
          const v = [0, 0, 0];
          for (let i = 0; i < n; i++) {
            v[0] += resp[i][j] * (X[i][0] - mu[0]) ** 2;
            v[1] += resp[i][j] * (X[i][1] - mu[1]) ** 2;
            v[2] += resp[i][j] * (X[i][2] - mu[2]) ** 2;
          }
          v[0] /= Nj;
          v[1] /= Nj;
          v[2] /= Nj;

          // Floor variance to prevent numerical issues
          vars[j] = v.map(x => Math.max(50, x));

          // Update weight
          weights[j] = Nj / n;
        }
      }
    }

    // Compute log-likelihood
    let ll = 0;
    for (let i = 0; i < n; i++) {
      let s = 0;
      for (let j = 0; j < k; j++) {
        let p = 1;
        for (let t = 0; t < d; t++) {
          const diff = X[i][t] - means[j][t];
          const v = vars[j][t];
          p *= Math.exp(-0.5 * diff * diff / v) / Math.sqrt(2 * Math.PI * v);
        }
        s += weights[j] * p;
      }
      ll += Math.log(Math.max(1e-12, s));
    }

    // Compute BIC: -2 * log-likelihood + params * log(n)
    // Parameters: k * (d means + d vars) + (k-1) weights
    const params = k * (d + d) + (k - 1);
    const bic = -2 * ll + params * Math.log(n);

    return {
      k,
      means,
      vars,
      weights,
      bic,
      ll,
    };
  }

  // Test all K values and select the one with lowest BIC
  let best: GMMResult | null = null;

  for (let k = Kmin; k <= Kmax; k++) {
    const run = em(k);
    if (!best || run.bic < best.bic) {
      best = run;
    }
  }

  if (!best) {
    throw new Error('Failed to find optimal K');
  }

  return best;
}

/**
 * Helper function to convert GMM result to cluster format compatible with kmeansRGB
 * 
 * @param gmmResult GMM result from gmmDiagBIC
 * @returns Array of RGB centroids suitable for K-Means initialization
 */
export function gmmResultToCentroids(gmmResult: GMMResult): number[][] {
  return gmmResult.means.map(mean => [
    Math.round(mean[0]),
    Math.round(mean[1]),
    Math.round(mean[2]),
  ]);
}

/**
 * Get optimal K value from GMM result
 * 
 * @param gmmResult GMM result from gmmDiagBIC
 * @returns Optimal number of clusters
 */
export function getOptimalK(gmmResult: GMMResult): number {
  return gmmResult.k;
}

/**
 * Image color extraction utilities
 * Extracts colors from gemstone images for analysis
 * Enhanced with improved accuracy algorithms
 */

import { deltaE2000 } from './deltaE2000';
import { rgbToXyz, xyzToLab, Whitepoint } from './colorConversions';

export interface ColorSample {
  hex: string;
  rgb: { r: number; g: number; b: number };
  lab: { L: number; a: number; b: number };
  xyz: { x: number; y: number; z: number };
  percentage: number;
  x: number;
  y: number;
  weight?: number; // Weight for statistical calculations
}

export interface ImageAnalysis {
  primaryColor: ColorSample;
  secondaryColors: ColorSample[];
  allColors: ColorSample[];
  luminance: number;
  saturation: number;
  colorPurity: number;
}

/**
 * Masking options for background detection
 */
export interface MaskingOptions {
  white: boolean;        // Filter bright/neutral pixels
  black: boolean;        // Filter very dark pixels
  lowSat: boolean;       // Filter low saturation pixels
  smart: boolean;        // Smart mask (border detection)
  wThr: number;          // White threshold (180-250)
  bThr: number;          // Black threshold (0-60)
  sThr: number;          // Saturation threshold (0-30)
}

/**
 * Default masking options
 */
export const DEFAULT_MASKING_OPTIONS: MaskingOptions = {
  white: true,
  black: true,
  lowSat: true,
  smart: true,
  wThr: 220,
  bThr: 25,
  sThr: 8,
};

/**
 * Convert RGB to HSV
 */
function rgbToHsv(r: number, g: number, b: number): [number, number, number] {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const d = max - min;
  let h = 0;
  if (d === 0) {
    h = 0;
  } else if (max === r) {
    h = 60 * (((g - b) / d) % 6);
  } else if (max === g) {
    h = 60 * (((b - r) / d) + 2);
  } else {
    h = 60 * (((r - g) / d) + 4);
  }
  if (h < 0) h += 360;
  const s = max === 0 ? 0 : (d / max);
  const v = max;
  return [h, s * 100, v * 100];
}

/**
 * Calculate luminance (relative brightness)
 */
function luma(r: number, g: number, b: number): number {
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/**
 * Detect and remove background from image
 * Returns a mask indicating which pixels belong to the gemstone
 */
function detectGemstoneMask(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  options: MaskingOptions = DEFAULT_MASKING_OPTIONS
): boolean[][] {
  const mask: boolean[][] = [];
  const backgroundTolerance = 40; // Tolerance for background color detection

  // First pass: detect background colors (typically white, light gray, or very light colors)
  const backgroundColors: { r: number; g: number; b: number }[] = [];

  // Sample corners and edges for background color
  const backgroundSamples = [
    // Corners
    { x: 0, y: 0 },
    { x: width - 1, y: 0 },
    { x: 0, y: height - 1 },
    { x: width - 1, y: height - 1 },
    // Edge centers
    { x: Math.floor(width / 2), y: 0 },
    { x: Math.floor(width / 2), y: height - 1 },
    { x: 0, y: Math.floor(height / 2) },
    { x: width - 1, y: Math.floor(height / 2) },
  ];

  for (const sample of backgroundSamples) {
    const imageData = ctx.getImageData(sample.x, sample.y, 1, 1);
    const [r, g, b] = imageData.data;
    if (imageData.data[3] > 128) {
      backgroundColors.push({ r, g, b });
    }
  }

  // Calculate average background color
  const avgBg = backgroundColors.length > 0
    ? backgroundColors.reduce(
        (acc, c) => ({ r: acc.r + c.r, g: acc.g + c.g, b: acc.b + c.b }),
        { r: 0, g: 0, b: 0 }
      )
    : { r: 255, g: 255, b: 255 };
  if (backgroundColors.length > 0) {
    avgBg.r /= backgroundColors.length;
    avgBg.g /= backgroundColors.length;
    avgBg.b /= backgroundColors.length;
  }

  // Sample borders for smart detection
  const borders: [number, number, number][] = [];
  if (options.smart) {
    const step = Math.max(1, Math.floor(Math.min(width, height) / 64));
    const sample = (x: number, y: number) => {
      const imageData = ctx.getImageData(x, y, 1, 1);
      borders.push([imageData.data[0], imageData.data[1], imageData.data[2]]);
    };
    for (let x = 0; x < width; x += step) {
      sample(x, 0);
      sample(x, height - 1);
    }
    for (let y = 0; y < height; y += step) {
      sample(0, y);
      sample(width - 1, y);
    }
  }

  // Function to check if pixel should be ignored
  const ignorePx = (r: number, g: number, b: number): boolean => {
    const [hue, sat, val] = rgbToHsv(r, g, b);
    const L = luma(r, g, b);

    // White/neutral filter
    if (options.white && L > options.wThr && sat < 30) return true;

    // Black filter
    if (options.black && L < options.bThr) return true;

    // Low saturation filter
    if (options.lowSat && sat < options.sThr) return true;

    // Smart mask (border detection)
    if (options.smart) {
      for (const [br, bg, bb] of borders) {
        const [bh, bs, bv] = rgbToHsv(br, bg, bb);
        const dH = Math.min(Math.abs(hue - bh), 360 - Math.abs(hue - bh));
        const dS = Math.abs(sat - bs);
        const dV = Math.abs(val - bv);
        const dL = Math.abs(L - luma(br, bg, bb));
        if (dH < 18 && dS < 28 && dV < 28) return true;
        if (dL < 22 && sat < 10) return true;
      }
    }

    return false;
  };

  // Initialize mask
  for (let y = 0; y < height; y++) {
    mask[y] = [];
    for (let x = 0; x < width; x++) {
      mask[y][x] = false;
    }
  }

  // Second pass: identify gemstone pixels
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const imageData = ctx.getImageData(x, y, 1, 1);
      const [r, g, b, a] = imageData.data;

      // Skip transparent pixels
      if (a < 128) {
        mask[y][x] = false;
        continue;
      }

      // Check if pixel should be ignored based on masking options
      if (ignorePx(r, g, b)) {
        mask[y][x] = false;
        continue;
      }

      // Check if pixel is similar to background
      const distToBg = Math.sqrt(
        Math.pow(r - avgBg.r, 2) +
        Math.pow(g - avgBg.g, 2) +
        Math.pow(b - avgBg.b, 2)
      );

      // Pixel is part of gemstone if not too close to background
      if (distToBg > backgroundTolerance) {
        mask[y][x] = true;
      }
    }
  }

  // Third pass: flood fill from center to ensure we capture the gemstone
  const visited: boolean[][] = [];
  for (let y = 0; y < height; y++) {
    visited[y] = new Array(width).fill(false);
  }

  const centerX = Math.floor(width / 2);
  const centerY = Math.floor(height / 2);

  // Flood fill from center
  const queue: { x: number; y: number }[] = [{ x: centerX, y: centerY }];
  while (queue.length > 0) {
    const { x, y } = queue.shift()!;
    if (x < 0 || x >= width || y < 0 || y >= height || visited[y][x]) continue;

    visited[y][x] = true;
    const imageData = ctx.getImageData(x, y, 1, 1);
    const [r, g, b, a] = imageData.data;

    if (a < 128) continue;

    // If pixel is not background-like, mark it as gemstone
    const brightness = (r + g + b) / 3;
    const distToBg = Math.sqrt(
      Math.pow(r - avgBg.r, 2) +
      Math.pow(g - avgBg.g, 2) +
      Math.pow(b - avgBg.b, 2)
    );

    if (distToBg > backgroundTolerance && brightness < 250) {
      mask[y][x] = true;
      // Add neighbors to queue
      queue.push({ x: x + 1, y });
      queue.push({ x: x - 1, y });
      queue.push({ x, y: y + 1 });
      queue.push({ x, y: y - 1 });
    }
  }

  return mask;
}

/**
 * Extract colors from image using canvas, focusing only on gemstone pixels
 */
export async function extractColorsFromImage(
  imageFile: File,
  sampleSize: number = 10000,
  cropRegion?: { x: number; y: number; width: number; height: number },
  whitepoint: Whitepoint = 'D65',
  kValue?: number | null,
  maskingOptions?: MaskingOptions,
  externalAlpha?: Uint8ClampedArray
): Promise<ImageAnalysis> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(imageFile);

    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          reject(new Error('Could not get canvas context'));
          return;
        }

        canvas.width = img.width;
        canvas.height = img.height;
        ctx.drawImage(img, 0, 0);

        // Detect gemstone mask (which pixels belong to the gemstone)
        // If external alpha is provided (from GrabCut), use it; otherwise use automatic detection
        let mask: boolean[][];
        if (externalAlpha) {
          // Use external alpha mask from GrabCut
          mask = [];
          for (let y = 0; y < img.height; y++) {
            mask[y] = [];
            for (let x = 0; x < img.width; x++) {
              const idx = y * img.width + x;
              mask[y][x] = externalAlpha[idx] > 128;
            }
          }
        } else {
          // Use automatic mask detection
          mask = detectGemstoneMask(ctx, img.width, img.height, maskingOptions || DEFAULT_MASKING_OPTIONS);
        }

        // Determine analysis region
        let startX = 0;
        let startY = 0;
        let endX = img.width;
        let endY = img.height;

        if (cropRegion) {
          startX = Math.max(0, cropRegion.x);
          startY = Math.max(0, cropRegion.y);
          endX = Math.min(img.width, cropRegion.x + cropRegion.width);
          endY = Math.min(img.height, cropRegion.y + cropRegion.height);
        }

        // Adaptive sampling: more samples in important areas
        const pixels: ColorSample[] = [];
        const baseStep = Math.max(1, Math.floor(((endX - startX) * (endY - startY)) / sampleSize));

        // First pass: uniform sampling
        for (let y = startY; y < endY; y += baseStep) {
          for (let x = startX; x < endX; x += baseStep) {
            if (!mask[y] || !mask[y][x]) continue;

            const imageData = ctx.getImageData(x, y, 1, 1);
            const [r, g, b] = imageData.data;

            if (imageData.data[3] < 128) continue;

            const hex = rgbToHex(r, g, b);
            const rgb = { r: r / 255, g: g / 255, b: b / 255 };
            const xyz = rgbToXyz(rgb);
            const lab = xyzToLab(xyz, whitepoint);

            // Calculate weight based on color saturation (more saturated = more important)
            const chroma = Math.sqrt(lab.a ** 2 + lab.b ** 2);
            const weight = 1 + (chroma / 50); // Weight by chroma

            pixels.push({
              hex,
              rgb: { r, g, b },
              lab,
              xyz,
              percentage: 0,
              x,
              y,
              weight,
            });
          }
        }

        // Second pass: additional samples in high-contrast areas (edges, facets)
        const additionalSamples = Math.floor(sampleSize * 0.3); // 30% more samples
        const fineStep = Math.max(1, baseStep / 2);
        let added = 0;

        for (let y = startY; y < endY && added < additionalSamples; y += fineStep) {
          for (let x = startX; x < endX && added < additionalSamples; x += fineStep) {
            if (!mask[y] || !mask[y][x]) continue;

            // Check if this is an edge/high-contrast area
            const isEdge = detectEdge(ctx, x, y, mask, img.width, img.height);
            if (!isEdge && Math.random() > 0.3) continue; // Only sample edges with higher probability

            const imageData = ctx.getImageData(x, y, 1, 1);
            const [r, g, b] = imageData.data;

            if (imageData.data[3] < 128) continue;

            const hex = rgbToHex(r, g, b);
            const rgb = { r: r / 255, g: g / 255, b: b / 255 };
            const xyz = rgbToXyz(rgb);
            const lab = xyzToLab(xyz, whitepoint);

            const chroma = Math.sqrt(lab.a ** 2 + lab.b ** 2);
            const weight = 1.5 + (chroma / 50); // Higher weight for edge samples

            pixels.push({
              hex,
              rgb: { r, g, b },
              lab,
              xyz,
              percentage: 0,
              x,
              y,
              weight,
            });
            added++;
          }
        }

        // Cluster similar colors
        const clustered = clusterColors(pixels, whitepoint, kValue);

        // Calculate primary and secondary colors
        const sorted = clustered.sort((a, b) => b.percentage - a.percentage);
        const primaryColor = sorted[0];
        const secondaryColors = sorted.slice(1, 5); // Top 4 secondary colors

        // Calculate overall metrics with weighted statistics
        const totalWeight = clustered.reduce((sum, c) => sum + (c.weight || c.percentage), 0);

        // Weighted average luminance
        const avgL = totalWeight > 0
          ? clustered.reduce((sum, c) => sum + c.lab.L * (c.weight || c.percentage), 0) / totalWeight
          : clustered.reduce((sum, c) => sum + c.lab.L, 0) / clustered.length;

        // Weighted average saturation
        const avgS = totalWeight > 0
          ? clustered.reduce((sum, c) => {
              const chroma = Math.sqrt(c.lab.a ** 2 + c.lab.b ** 2);
              return sum + chroma * (c.weight || c.percentage);
            }, 0) / totalWeight
          : clustered.reduce((sum, c) => {
              const chroma = Math.sqrt(c.lab.a ** 2 + c.lab.b ** 2);
              return sum + chroma;
            }, 0) / clustered.length;

        // Color purity (how close colors are to primary) using CIEDE2000
        const colorPurity = calculateColorPurity(clustered, primaryColor);

        resolve({
          primaryColor,
          secondaryColors,
          allColors: clustered,
          luminance: avgL,
          saturation: avgS,
          colorPurity,
        });

        URL.revokeObjectURL(url);
      } catch (error) {
        URL.revokeObjectURL(url);
        reject(error);
      }
    };

    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error('Failed to load image'));
    };

    img.src = url;
  });
}

/**
 * Cluster similar colors together using improved K-Means with CIEDE2000
 * Uses CIEDE2000 for perceptually uniform color distance
 */
function clusterColors(colors: ColorSample[], whitepoint: Whitepoint = 'D65', kValue?: number | null): ColorSample[] {
  if (colors.length === 0) return [];
  if (colors.length === 1) {
    colors[0].percentage = 100;
    return colors;
  }

  // Use K-Means clustering with CIEDE2000
  // If kValue is provided, use it; otherwise use adaptive calculation
  const k = kValue !== null && kValue !== undefined 
    ? Math.max(3, Math.min(20, kValue)) // Clamp between 3 and 20
    : Math.min(Math.max(3, Math.floor(colors.length / 100)), 20); // Adaptive k
  const clusters = kMeansClustering(colors, k, 20, whitepoint);

  // Normalize percentages
  const total = clusters.reduce((sum, c) => sum + c.percentage, 0);
  if (total > 0) {
    clusters.forEach(c => {
      c.percentage = (c.percentage / total) * 100;
    });
  }

  return clusters;
}

/**
 * K-Means clustering using CIEDE2000 distance metric
 */
function kMeansClustering(colors: ColorSample[], k: number, maxIterations: number = 20, whitepoint: Whitepoint = 'D65'): ColorSample[] {
  if (colors.length === 0) return [];
  if (k >= colors.length) {
    // Each color is its own cluster
    return colors.map(c => ({ ...c, percentage: 1 }));
  }

  // Initialize centroids using k-means++ (better initialization)
  const centroids: ColorSample[] = [];

  // First centroid: random or most representative
  const firstIdx = Math.floor(Math.random() * colors.length);
  centroids.push({ ...colors[firstIdx] });

  // Select remaining centroids using k-means++
  for (let i = 1; i < k; i++) {
    const distances: number[] = [];
    for (const color of colors) {
      let minDist = Infinity;
      for (const centroid of centroids) {
        const dist = deltaE2000(color.lab, centroid.lab);
        if (dist < minDist) minDist = dist;
      }
      distances.push(minDist * minDist); // Square for probability weighting
    }

    // Select color with highest distance (farthest from existing centroids)
    const sum = distances.reduce((a, b) => a + b, 0);
    let random = Math.random() * sum;
    let selectedIdx = 0;
    for (let j = 0; j < distances.length; j++) {
      random -= distances[j];
      if (random <= 0) {
        selectedIdx = j;
        break;
      }
    }
    centroids.push({ ...colors[selectedIdx] });
  }

  // K-Means iterations
  let clusters: ColorSample[] = [];
  for (let iter = 0; iter < maxIterations; iter++) {
    // Assign colors to nearest centroid
    const assignments: number[] = new Array(colors.length).fill(-1);
    const clusterColors: ColorSample[][] = new Array(k).fill(null).map(() => []);
    const clusterWeights: number[] = new Array(k).fill(0);

    for (let i = 0; i < colors.length; i++) {
      let minDist = Infinity;
      let nearestCluster = 0;

      for (let j = 0; j < k; j++) {
        const dist = deltaE2000(colors[i].lab, centroids[j].lab);
        if (dist < minDist) {
          minDist = dist;
          nearestCluster = j;
        }
      }

      assignments[i] = nearestCluster;
      clusterColors[nearestCluster].push(colors[i]);
      clusterWeights[nearestCluster] += colors[i].weight || 1;
    }

    // Update centroids (weighted average)
    let converged = true;
    for (let j = 0; j < k; j++) {
      if (clusterColors[j].length === 0) continue;

      const totalWeight = clusterWeights[j];
      if (totalWeight === 0) continue;

      let newL = 0, newA = 0, newB = 0;
      let newR = 0, newG = 0, newBl = 0;

      for (const color of clusterColors[j]) {
        const weight = color.weight || 1;
        newL += color.lab.L * weight;
        newA += color.lab.a * weight;
        newB += color.lab.b * weight;
        newR += color.rgb.r * weight;
        newG += color.rgb.g * weight;
        newBl += color.rgb.b * weight;
      }

      const newCentroid: ColorSample = {
        hex: '', // Will be recalculated
        rgb: { r: newR / totalWeight, g: newG / totalWeight, b: newBl / totalWeight },
        lab: { L: newL / totalWeight, a: newA / totalWeight, b: newB / totalWeight },
        xyz: { x: 0, y: 0, z: 0 }, // Will be recalculated if needed
        percentage: clusterColors[j].length,
        x: 0,
        y: 0,
      };

      // Recalculate hex and xyz from averaged Lab
      newCentroid.hex = labToHex(newCentroid.lab);
      newCentroid.xyz = labToXyz(newCentroid.lab);

      // Check convergence
      const dist = deltaE2000(newCentroid.lab, centroids[j].lab);
      if (dist > 0.5) converged = false;

      centroids[j] = newCentroid;
    }

    if (converged && iter > 2) break;
  }

  // Create final clusters with percentages
  clusters = centroids.map((centroid, idx) => {
    // Count colors assigned to this cluster
    let count = 0;
    for (let i = 0; i < colors.length; i++) {
      const dist = deltaE2000(colors[i].lab, centroid.lab);
      // Find which centroid is nearest
      let minDist = dist;
      let nearestIdx = idx;
      for (let j = 0; j < k; j++) {
        const d = deltaE2000(colors[i].lab, centroids[j].lab);
        if (d < minDist) {
          minDist = d;
          nearestIdx = j;
        }
      }
      if (nearestIdx === idx) {
        count++;
      }
    }

    return {
      ...centroid,
      percentage: count,
    };
  });

  // Filter out empty clusters and sort by percentage
  return clusters
    .filter(c => c.percentage > 0)
    .sort((a, b) => b.percentage - a.percentage);
}

/**
 * Convert Lab to Hex (approximate, via XYZ and RGB)
 */
function labToHex(lab: { L: number; a: number; b: number }): string {
  const xyz = labToXyz(lab);
  const rgb = xyzToRgb(xyz);
  return rgbToHex(
    Math.round(Math.max(0, Math.min(255, rgb.r * 255))),
    Math.round(Math.max(0, Math.min(255, rgb.g * 255))),
    Math.round(Math.max(0, Math.min(255, rgb.b * 255)))
  );
}

/**
 * Convert Lab to XYZ
 */
function labToXyz(lab: { L: number; a: number; b: number }): { x: number; y: number; z: number } {
  const Xn = 0.95047;
  const Yn = 1.00000;
  const Zn = 1.08883;

  const fy = (lab.L + 16) / 116;
  const fx = lab.a / 500 + fy;
  const fz = fy - lab.b / 200;

  const xr = fx > 0.206897 ? fx * fx * fx : (fx - 16 / 116) / 7.787;
  const yr = fy > 0.206897 ? fy * fy * fy : (fy - 16 / 116) / 7.787;
  const zr = fz > 0.206897 ? fz * fz * fz : (fz - 16 / 116) / 7.787;

  return {
    x: xr * Xn,
    y: yr * Yn,
    z: zr * Zn,
  };
}

/**
 * Convert XYZ to RGB
 */
function xyzToRgb(xyz: { x: number; y: number; z: number }): { r: number; g: number; b: number } {
  const gamma = (u: number) => u <= 0.0031308 ? 12.92 * u : 1.055 * Math.pow(u, 1 / 2.4) - 0.055;

  const r = gamma(xyz.x * 3.2404542 + xyz.y * -1.5371385 + xyz.z * -0.4985314);
  const g = gamma(xyz.x * -0.9692660 + xyz.y * 1.8760108 + xyz.z * 0.0415560);
  const b = gamma(xyz.x * 0.0556434 + xyz.y * -0.2040259 + xyz.z * 1.0572252);

  return {
    r: Math.max(0, Math.min(1, r)),
    g: Math.max(0, Math.min(1, g)),
    b: Math.max(0, Math.min(1, b)),
  };
}

/**
 * Calculate Delta E between two Lab colors (legacy, now uses CIEDE2000)
 * Kept for backward compatibility, but CIEDE2000 is used in clustering
 * Note: This function is not currently used but kept for potential future use
 */
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function calculateDeltaE(lab1: { L: number; a: number; b: number }, lab2: { L: number; a: number; b: number }): number {
  // Use CIEDE2000 for better perceptual accuracy
  return deltaE2000(lab1, lab2);
}

/**
 * Calculate color purity (how uniform the colors are) using CIEDE2000
 */
function calculateColorPurity(colors: ColorSample[], primary: ColorSample): number {
  if (colors.length === 0) return 0;

  const totalWeight = colors.reduce((sum, c) => sum + (c.weight || c.percentage), 0);

  // Weighted average Delta E using CIEDE2000
  const avgDeltaE = totalWeight > 0
    ? colors.reduce((sum, c) => {
        const deltaE = deltaE2000(c.lab, primary.lab);
        return sum + deltaE * (c.weight || c.percentage);
      }, 0) / totalWeight
    : colors.reduce((sum, c) => {
        return sum + deltaE2000(c.lab, primary.lab);
      }, 0) / colors.length;

  // Normalize to 0-100 (lower delta E = higher purity)
  // CIEDE2000 values: < 1 = not perceptible, < 3 = slight difference, < 10 = noticeable
  return Math.max(0, Math.min(100, 100 - (avgDeltaE * 3)));
}

/**
 * Detect if a pixel is on an edge (high contrast area)
 */
function detectEdge(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  mask: boolean[][],
  width: number,
  height: number
): boolean {
  const neighbors = [
    { x: x - 1, y },
    { x: x + 1, y },
    { x, y: y - 1 },
    { x, y: y + 1 },
  ];

  let validNeighbors = 0;
  let contrastSum = 0;

  const centerData = ctx.getImageData(x, y, 1, 1);
  const centerLum = (centerData.data[0] + centerData.data[1] + centerData.data[2]) / 3;

  for (const neighbor of neighbors) {
    if (neighbor.x < 0 || neighbor.x >= width || neighbor.y < 0 || neighbor.y >= height) continue;
    if (!mask[neighbor.y] || !mask[neighbor.y][neighbor.x]) continue;

    const neighborData = ctx.getImageData(neighbor.x, neighbor.y, 1, 1);
    const neighborLum = (neighborData.data[0] + neighborData.data[1] + neighborData.data[2]) / 3;

    const contrast = Math.abs(centerLum - neighborLum);
    contrastSum += contrast;
    validNeighbors++;
  }

  if (validNeighbors === 0) return false;

  const avgContrast = contrastSum / validNeighbors;
  return avgContrast > 15; // Threshold for edge detection
}

/**
 * Convert RGB to Hex
 */
function rgbToHex(r: number, g: number, b: number): string {
  return `#${[r, g, b].map(x => {
    const hex = x.toString(16);
    return hex.length === 1 ? '0' + hex : hex;
  }).join('')}`;
}

// Note: rgbToXyz and xyzToLab are now imported from colorConversions.ts

/**
 * Analyze image regions (center, facets, shadows) - only gemstone pixels
 */
export async function analyzeImageRegions(
  imageFile: File,
  cropRegion?: { x: number; y: number; width: number; height: number },
  whitepoint: Whitepoint = 'D65',
  kValue?: number | null,
  maskingOptions?: MaskingOptions
): Promise<{
  center: ColorSample[];
  facets: ColorSample[];
  shadows: ColorSample[];
}> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(imageFile);

    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          reject(new Error('Could not get canvas context'));
          return;
        }

        canvas.width = img.width;
        canvas.height = img.height;
        ctx.drawImage(img, 0, 0);

        // Detect gemstone mask
        const mask = detectGemstoneMask(ctx, img.width, img.height, maskingOptions || DEFAULT_MASKING_OPTIONS);

        // Determine analysis region
        let startX = 0;
        let startY = 0;
        let endX = img.width;
        let endY = img.height;

        if (cropRegion) {
          startX = Math.max(0, cropRegion.x);
          startY = Math.max(0, cropRegion.y);
          endX = Math.min(img.width, cropRegion.x + cropRegion.width);
          endY = Math.min(img.height, cropRegion.y + cropRegion.height);
        }

        const center: ColorSample[] = [];
        const facets: ColorSample[] = [];
        const shadows: ColorSample[] = [];

        const centerX = (startX + endX) / 2;
        const centerY = (startY + endY) / 2;
        const centerRadius = Math.min(endX - startX, endY - startY) * 0.2;

        // Improved region detection with edge-aware sampling
        const step = 3; // Smaller step for better region detection

        for (let y = startY; y < endY; y += step) {
          for (let x = startX; x < endX; x += step) {
            // Only process gemstone pixels
            if (!mask[y] || !mask[y][x]) continue;

            const imageData = ctx.getImageData(x, y, 1, 1);
            const [r, g, b] = imageData.data;

            if (imageData.data[3] < 128) continue;

            const hex = rgbToHex(r, g, b);
            const rgb = { r: r / 255, g: g / 255, b: b / 255 };
            const xyz = rgbToXyz(rgb);
            const lab = xyzToLab(xyz, whitepoint);

            // Detect if this is an edge (facet boundary)
            const isEdge = detectEdge(ctx, x, y, mask, img.width, img.height);

            const sample: ColorSample = {
              hex,
              rgb: { r, g, b },
              lab,
              xyz,
              percentage: 0,
              x,
              y,
              weight: isEdge ? 1.5 : 1.0, // Higher weight for edges (facets)
            };

            const distFromCenter = Math.sqrt((x - centerX) ** 2 + (y - centerY) ** 2);
            const luminance = lab.L;
            const chroma = Math.sqrt(lab.a ** 2 + lab.b ** 2);

            // Improved region classification
            if (distFromCenter < centerRadius) {
              center.push(sample);
            } else if (isEdge || (luminance > 55 && chroma > 10)) {
              // Facets: high luminance OR edges (facet boundaries) with good color
              facets.push(sample);
            } else if (luminance < 45 || chroma < 5) {
              // Shadows: low luminance OR very desaturated
              shadows.push(sample);
            }
          }
        }

        URL.revokeObjectURL(url);
        resolve({
          center: clusterColors(center, whitepoint, kValue),
          facets: clusterColors(facets, whitepoint, kValue),
          shadows: clusterColors(shadows, whitepoint, kValue),
        });
      } catch (error) {
        URL.revokeObjectURL(url);
        reject(error);
      }
    };

    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error('Failed to load image'));
    };

    img.src = url;
  });
}

// Export helper functions for enhanced color extraction
export { detectGemstoneMask, calculateColorPurity, rgbToHex, rgbToHsv, luma, detectEdge };

/**
 * OpenCV.js integration utilities
 * Provides GrabCut segmentation and brush tools for precise gemstone masking
 */

declare global {
  interface Window {
    cv: any;
  }
}

export type BrushMode = 'RECT' | 'FG' | 'BG';

export interface BrushStroke {
  x: number;
  y: number;
  r: number;
}

export interface RectRegion {
  x: number;
  y: number;
  w: number;
  h: number;
}

/**
 * Load OpenCV.js dynamically
 * Tries multiple CDN URLs for reliability
 */
export async function loadOpenCV(): Promise<boolean> {
  if (window.cv && window.cv.Mat) {
    console.log('OpenCV.js bereits geladen');
    return true;
  }

  // Try multiple CDN URLs in order
  // Note: OpenCV.js is a large library (~8MB) and may not be available on all CDNs
  // If all fail, the system will fall back to automatic segmentation
  const urls = [
    'https://docs.opencv.org/4.10.0/opencv.js',
    'https://docs.opencv.org/4.9.0/opencv.js',
    'https://docs.opencv.org/4.8.0/opencv.js',
    'https://cdn.jsdelivr.net/gh/opencv/opencv@4.8.0/opencv.js',
  ];

  for (let i = 0; i < urls.length; i++) {
    try {
      const success = await tryLoadOpenCV(urls[i]);
      if (success) {
        return true;
      }
    } catch (error) {
      console.warn(`OpenCV.js konnte nicht von ${urls[i]} geladen werden.`);
      if (i === urls.length - 1) {
        // Last URL failed - return false instead of throwing
        // This allows the system to gracefully fall back to automatic segmentation
        console.warn('OpenCV.js konnte von keiner Quelle geladen werden. Automatische Segmentierung wird verwendet.');
        return false;
      }
    }
  }

  // If we get here, all URLs failed
  console.warn('OpenCV.js konnte nicht geladen werden. Automatische Segmentierung wird verwendet.');
  return false;
}

/**
 * Try to load OpenCV.js from a specific URL
 */
function tryLoadOpenCV(url: string): Promise<boolean> {
  return new Promise((resolve, reject) => {
    // Check if script already exists
    const existingScript = document.querySelector(`script[src="${url}"]`);
    if (existingScript) {
      // Script already loading, wait for it
      const waitForCV = () => {
        if (window.cv && window.cv.Mat) {
          resolve(true);
        } else {
          setTimeout(waitForCV, 200);
        }
      };
      waitForCV();
      return;
    }

    const script = document.createElement('script');
    script.src = url;
    script.async = true;
    script.crossOrigin = 'anonymous';

    let resolved = false;

    script.onload = () => {
      // Wait for OpenCV to be ready
      // OpenCV.js can be loaded in different ways:
      // 1. Directly as window.cv
      // 2. As a Promise (cv.then)
      // 3. As cv.onRuntimeInitialized callback

      let attempts = 0;
      const maxAttempts = 50; // 10 seconds max (50 * 200ms)

      const checkCV = () => {
        attempts++;

        // Check if cv is available directly
        if (window.cv) {
          // Check if it's a Promise
          if (typeof window.cv.then === 'function') {
            // It's a Promise, wait for it
            window.cv.then((cv: any) => {
              window.cv = cv;
              if (window.cv.Mat && typeof window.cv.Mat === 'function') {
                console.log(`OpenCV.js erfolgreich geladen von ${url} (Promise)`);
                if (!resolved) {
                  resolved = true;
                  resolve(true);
                }
              } else {
                if (!resolved && attempts < maxAttempts) {
                  setTimeout(checkCV, 200);
                } else if (!resolved) {
                  resolved = true;
                  reject(new Error('OpenCV Promise resolved but Mat not available'));
                }
              }
            }).catch((error: any) => {
              if (!resolved) {
                resolved = true;
                reject(new Error(`OpenCV Promise rejected: ${error}`));
              }
            });
            return;
          }

          // Direct cv object
          if (window.cv.Mat && typeof window.cv.Mat === 'function') {
            console.log(`OpenCV.js erfolgreich geladen von ${url}`);
            if (!resolved) {
              resolved = true;
              resolve(true);
            }
            return;
          }

          // Check for onRuntimeInitialized
          if (window.cv.onRuntimeInitialized) {
            window.cv.onRuntimeInitialized = () => {
              if (window.cv.Mat && typeof window.cv.Mat === 'function') {
                console.log(`OpenCV.js erfolgreich geladen von ${url} (onRuntimeInitialized)`);
                if (!resolved) {
                  resolved = true;
                  resolve(true);
                }
              }
            };
            return;
          }
        }

        // Continue waiting
        if (attempts < maxAttempts) {
          setTimeout(checkCV, 200);
        } else {
          if (!resolved) {
            resolved = true;
            reject(new Error(`OpenCV failed to initialize - timeout after ${maxAttempts * 200}ms`));
          }
        }
      };

      checkCV();
    };

    script.onerror = (error) => {
      // Don't log as error if it's just a network issue - this is expected for some CDNs
      console.warn(`OpenCV.js konnte nicht von ${url} geladen werden. Versuche nächste URL...`);
      if (!resolved) {
        resolved = true;
        reject(new Error(`Failed to load OpenCV.js from ${url}`));
      }
    };

    document.head.appendChild(script);

    // Timeout fallback
    setTimeout(() => {
      if (!resolved && !window.cv) {
        resolved = true;
        reject(new Error(`OpenCV.js loading timeout from ${url}`));
      }
    }, 15000); // 15 seconds total timeout
  });
}

/**
 * Apply GrabCut segmentation with brush seeds
 */
export function applyGrabCut(
  imageData: ImageData,
  fgStrokes: BrushStroke[],
  bgStrokes: BrushStroke[],
  rectRegion: RectRegion | null
): Uint8ClampedArray | null {
  if (!window.cv) {
    return null;
  }

  try {
    const cv = window.cv;
    const { width, height, data } = imageData;

    // Create OpenCV Mat from ImageData
    const src = cv.matFromImageData(imageData);
    const mask = new cv.Mat.zeros(height, width, cv.CV_8UC1);
    const bgdModel = new cv.Mat();
    const fgdModel = new cv.Mat();

    // Apply brush seeds to mask
    const drawSeeds = (strokes: BrushStroke[], value: number) => {
      for (const stroke of strokes) {
        cv.circle(
          mask,
          new cv.Point(Math.round(stroke.x), Math.round(stroke.y)),
          Math.round(stroke.r),
          new cv.Scalar(value),
          -1
        );
      }
    };

    if (fgStrokes.length > 0) {
      drawSeeds(fgStrokes, cv.GC_FGD);
    }
    if (bgStrokes.length > 0) {
      drawSeeds(bgStrokes, cv.GC_BGD);
    }

    // Determine initialization mode and run GrabCut
    const hasStrokes = fgStrokes.length > 0 || bgStrokes.length > 0;

    if (hasStrokes) {
      // Use mask mode if we have brush strokes
      cv.grabCut(
        src,
        mask,
        new cv.Rect(),
        bgdModel,
        fgdModel,
        5,
        cv.GC_INIT_WITH_MASK
      );
    } else if (rectRegion) {
      // Use rect mode if we only have a rectangle
      // Normalize rectangle (handle negative width/height from dragging)
      const rx = Math.round(Math.min(rectRegion.x, rectRegion.x + rectRegion.w));
      const ry = Math.round(Math.min(rectRegion.y, rectRegion.y + rectRegion.h));
      const rw = Math.round(Math.abs(rectRegion.w));
      const rh = Math.round(Math.abs(rectRegion.h));

      // Ensure rectangle is valid and within image bounds
      const validX = Math.max(0, Math.min(rx, width - 1));
      const validY = Math.max(0, Math.min(ry, height - 1));
      const validW = Math.min(rw, width - validX);
      const validH = Math.min(rh, height - validY);

      if (validW > 10 && validH > 10) { // Minimum size: 10x10 pixels
        console.log('GrabCut mit Rechteck:', { x: validX, y: validY, w: validW, h: validH });
        cv.grabCut(
          src,
          mask,
          new cv.Rect(validX, validY, validW, validH),
          bgdModel,
          fgdModel,
          5,
          cv.GC_INIT_WITH_RECT
        );
      } else {
        // Invalid rectangle (too small or out of bounds), return null
        console.warn('Ungültiges Rechteck für GrabCut:', { x: validX, y: validY, w: validW, h: validH });
        src.delete();
        mask.delete();
        bgdModel.delete();
        fgdModel.delete();
        return null;
      }
    } else {
      // No strokes and no rectangle - return null (use automatic segmentation)
      src.delete();
      mask.delete();
      bgdModel.delete();
      fgdModel.delete();
      return null;
    }

    // Extract alpha channel from mask
    const alpha = new Uint8ClampedArray(width * height);
    for (let i = 0; i < width * height; i++) {
      const row = Math.floor(i / width);
      const col = i % width;
      const v = mask.ucharPtr(row, col)[0];
      alpha[i] = (v === cv.GC_FGD || v === cv.GC_PR_FGD) ? 255 : 0;
    }

    // Cleanup
    src.delete();
    mask.delete();
    bgdModel.delete();
    fgdModel.delete();

    return alpha;
  } catch (error) {
    console.error('GrabCut error:', error);
    return null;
  }
}

/**
 * Test Utilities for ICC Profile Functionality
 * 
 * Creates test ICC profiles and validates the parsing and whitepoint usage
 */

import { parseICC, parseICCFromFile, ICCProfile } from './iccParser';
import { xyzToLab, rgbToXyz, hexToRgb } from './colorConversions';

/**
 * Create a minimal test ICC profile with D50 whitepoint
 * 
 * ICC Profile Structure:
 * - Header: 128 bytes
 * - Tag count: 4 bytes
 * - Tag table: 12 bytes per tag
 * - Tag data
 */
export function createTestICCProfileD50(): Uint8Array {
  // D50 whitepoint: X=0.96422, Y=1.00000, Z=0.82521
  const wtptX = 0.96422;
  const wtptY = 1.00000;
  const wtptZ = 0.82521;

  // Convert to s15Fixed16 format
  const toFixed16 = (val: number): number => {
    const int = Math.floor(val);
    const frac = val - int;
    return (int << 16) | Math.floor(frac * 65536);
  };

  const buf = new Uint8Array(512); // Minimal size for test

  // ICC Profile Header (128 bytes)
  // Signature: "acsp" (ICC profile)
  buf[0] = 0x61; buf[1] = 0x63; buf[2] = 0x73; buf[3] = 0x70;

  // Version (4 bytes): 4.0.0.0
  buf[8] = 0x04; buf[9] = 0x00; buf[10] = 0x00; buf[11] = 0x00;

  // Device class: Display (0x6D6E7472)
  buf[12] = 0x6D; buf[13] = 0x6E; buf[14] = 0x74; buf[15] = 0x72;

  // Data color space: RGB (0x52474220)
  buf[16] = 0x52; buf[17] = 0x47; buf[18] = 0x42; buf[19] = 0x20;

  // PCS: XYZ (0x58595A20)
  buf[20] = 0x58; buf[21] = 0x59; buf[22] = 0x5A; buf[23] = 0x20;

  // Tag count: 1 (wtpt only)
  const tagCount = 1;
  buf[128] = 0x00; buf[129] = 0x00; buf[130] = 0x00; buf[131] = tagCount;

  // Tag table starts at offset 136
  // Tag: "wtpt" (white point)
  buf[136] = 0x77; buf[137] = 0x74; buf[138] = 0x70; buf[139] = 0x74; // "wtpt"

  // Tag offset: 200 (where tag data starts)
  const tagOffset = 200;
  buf[140] = (tagOffset >> 24) & 0xFF;
  buf[141] = (tagOffset >> 16) & 0xFF;
  buf[142] = (tagOffset >> 8) & 0xFF;
  buf[143] = tagOffset & 0xFF;

  // Tag size: 20 bytes (4 type + 4 reserved + 12 XYZ)
  const tagSize = 20;
  buf[144] = (tagSize >> 24) & 0xFF;
  buf[145] = (tagSize >> 16) & 0xFF;
  buf[146] = (tagSize >> 8) & 0xFF;
  buf[147] = tagSize & 0xFF;

  // Tag data at offset 200
  // Type signature: "XYZ "
  buf[200] = 0x58; buf[201] = 0x59; buf[202] = 0x5A; buf[203] = 0x20;

  // Reserved: 4 bytes (zeros)
  buf[204] = 0x00; buf[205] = 0x00; buf[206] = 0x00; buf[207] = 0x00;

  // XYZ values (s15Fixed16 format)
  const xFixed = toFixed16(wtptX);
  const yFixed = toFixed16(wtptY);
  const zFixed = toFixed16(wtptZ);

  buf[208] = (xFixed >> 24) & 0xFF;
  buf[209] = (xFixed >> 16) & 0xFF;
  buf[210] = (xFixed >> 8) & 0xFF;
  buf[211] = xFixed & 0xFF;

  buf[212] = (yFixed >> 24) & 0xFF;
  buf[213] = (yFixed >> 16) & 0xFF;
  buf[214] = (yFixed >> 8) & 0xFF;
  buf[215] = yFixed & 0xFF;

  buf[216] = (zFixed >> 24) & 0xFF;
  buf[217] = (zFixed >> 16) & 0xFF;
  buf[218] = (zFixed >> 8) & 0xFF;
  buf[219] = zFixed & 0xFF;

  return buf;
}

/**
 * Test ICC profile parsing
 */
export async function testICCParsing(): Promise<boolean> {
  console.log('🧪 Testing ICC Profile Parsing...');

  try {
    // Create test ICC profile
    const testICC = createTestICCProfileD50();

    // Parse it
    const profile = parseICC(testICC);

    // Validate
    if (!profile.wtpt) {
      console.error('❌ Failed: wtpt not found');
      return false;
    }

    const [x, y, z] = profile.wtpt;
    const expectedX = 0.96422;
    const expectedY = 1.00000;
    const expectedZ = 0.82521;

    const tolerance = 0.001;
    if (
      Math.abs(x - expectedX) > tolerance ||
      Math.abs(y - expectedY) > tolerance ||
      Math.abs(z - expectedZ) > tolerance
    ) {
      console.error(`❌ Failed: Whitepoint mismatch. Expected [${expectedX}, ${expectedY}, ${expectedZ}], got [${x.toFixed(5)}, ${y.toFixed(5)}, ${z.toFixed(5)}]`);
      return false;
    }

    console.log(`✅ ICC Parsing successful: wtpt = [${x.toFixed(5)}, ${y.toFixed(5)}, ${z.toFixed(5)}]`);
    return true;
  } catch (error) {
    console.error('❌ ICC Parsing failed:', error);
    return false;
  }
}

/**
 * Test whitepoint usage in color conversion
 */
export function testWhitepointUsage(): boolean {
  console.log('🧪 Testing Whitepoint Usage in Color Conversion...');

  try {
    // Test color: Pure red (#FF0000)
    const hex = '#FF0000';
    const rgb = hexToRgb(hex);
    if (!rgb) {
      console.error('❌ Failed: Could not convert hex to RGB');
      return false;
    }

    // Convert to XYZ
    const xyz = rgbToXyz(rgb);

    // Test 1: D65 (default)
    const labD65 = xyzToLab(xyz, 'D65');
    console.log(`  D65 Lab: L=${labD65.L.toFixed(2)}, a=${labD65.a.toFixed(2)}, b=${labD65.b.toFixed(2)}`);

    // Test 2: D50
    const labD50 = xyzToLab(xyz, 'D50');
    console.log(`  D50 Lab: L=${labD65.L.toFixed(2)}, a=${labD50.a.toFixed(2)}, b=${labD50.b.toFixed(2)}`);

    // Test 3: Custom whitepoint (D50 from ICC)
    const customWP: [number, number, number] = [0.96422, 1.00000, 0.82521];
    const labCustom = xyzToLab(xyz, 'D65', customWP);
    console.log(`  Custom (D50) Lab: L=${labCustom.L.toFixed(2)}, a=${labCustom.a.toFixed(2)}, b=${labCustom.b.toFixed(2)}`);

    // Verify that D50 and Custom (D50) produce similar results
    const diffL = Math.abs(labD50.L - labCustom.L);
    const diffA = Math.abs(labD50.a - labCustom.a);
    const diffB = Math.abs(labD50.b - labCustom.b);

    const tolerance = 0.1;
    if (diffL > tolerance || diffA > tolerance || diffB > tolerance) {
      console.warn(`⚠️  Warning: D50 and Custom (D50) differ: L=${diffL.toFixed(3)}, a=${diffA.toFixed(3)}, b=${diffB.toFixed(3)}`);
      // This is acceptable - slight differences due to implementation
    }

    console.log('✅ Whitepoint usage test passed');
    return true;
  } catch (error) {
    console.error('❌ Whitepoint usage test failed:', error);
    return false;
  }
}

/**
 * Run all ICC tests
 */
export async function runAllICCTests(): Promise<boolean> {
  console.log('🚀 Running ICC Profile Tests...\n');

  const test1 = await testICCParsing();
  console.log('');
  const test2 = testWhitepointUsage();
  console.log('');

  const allPassed = test1 && test2;

  if (allPassed) {
    console.log('✅ All ICC tests passed!');
  } else {
    console.log('❌ Some ICC tests failed');
  }

  return allPassed;
}

