                  <span className={navStyles.navLabel}>Details öffnen</span>
                  <span className={navStyles.navGlow} />
                </button>
              </div>
            </article>
          );
        })}
      </div>
      {/* Draggable Floating Card */}
      {selectedGemstone && (
        <>
          {/* Backdrop */}
          <div
            className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9998]"
            onClick={closeGemstone}
