        this.headers = new Headers(init.headers || {})
        this.bodyUsed = false
      }
      async json() { return typeof this.body === 'string' ? JSON.parse(this.body) : (this.body || {}) }
      async text() { return typeof this.body === 'string' ? this.body : (this.body ? JSON.stringify(this.body) : '') }
